/* ═══════════════════════════════════════════════════════════════
   Apricot Grove 杏林行 · data/daily-cases.js
   Daily Case bank. Loaded as a plain script (works on file:// too —
   fetch() of a local JSON would be blocked by CORS when Ting opens
   the files directly, so we expose a global instead).

   Each case:
     tier  1 Eight Principles · 2 Zang-Fu · 3 Qi/Blood/Fluids
           4 Combined patterns · 5 Easily-confused differentials
     pair  the pattern it is meant to be contrasted against
   ═══════════════════════════════════════════════════════════════ */
window.AG_CASES = [
{p:"風熱犯肺 Wind-Heat invading the Lung",tier:1,
 v:"A 22-year-old student, ill two days. Sore, swollen throat; fever with only slight aversion to cold; cough with thick yellow phlegm; thirst for cold drinks. Tongue: red at the tip, thin yellow coating. Pulse: floating and rapid.",
 vz:"22歲學生，病起兩日。咽喉腫痛，發熱重而惡寒輕，咳吐黃稠痰，口渴喜冷飲。舌尖紅、苔薄黃，脈浮數。",
 q:[{t:"Eight Principles — where and what nature?",z:"八綱：病位？病性？",
   o:[{a:"Exterior · Heat · Excess 表 · 熱 · 實",ok:1,n:"Two days old with a floating pulse = still <b>exterior</b>; fever>chills, thirst, yellow phlegm = <b>heat</b>. 新病脈浮屬表；發熱重、口渴、痰黃屬熱。"},
      {a:"Exterior · Cold · Excess 表 · 寒 · 實",ok:0,n:"Wind-cold gives chills>fever, clear thin phlegm, no thirst, a <b>tight</b> pulse. 風寒則惡寒重、痰稀白、不渴、脈緊。"},
      {a:"Interior · Heat · Excess 裡 · 熱 · 實",ok:0,n:"An interior heat pattern would have lost the floating pulse and the aversion to cold. 裡熱則脈不浮、不惡寒。"}]},
  {t:"Which organ is disturbed?",z:"病位在何臟腑？",
   o:[{a:"Lung 肺",ok:1,n:"Cough, phlegm, sore throat — the Lung governs qi and opens to the throat. 肺主氣司呼吸，其門戶在咽喉。"},
      {a:"Stomach 胃",ok:0,n:"No epigastric or digestive signs here. 無脘腹納食之症。"},
      {a:"Liver 肝",ok:0,n:"No wiry pulse, no hypochondriac or emotional signs. 無脈弦、無脅肋情志之症。"}]},
  {t:"Name the pattern.",z:"證型為何？",
   o:[{a:"風熱犯肺 Wind-Heat invading the Lung",ok:1,n:"Correct — the classic early wind-heat presentation."},
      {a:"痰熱壅肺 Phlegm-Heat obstructing the Lung",ok:0,n:"That is deeper and heavier: high fever, copious thick phlegm, rapid slippery pulse, often chest pain. 痰熱壅肺熱勢更重、痰多黏稠、脈滑數。"},
      {a:"肺陰虛 Lung Yin deficiency",ok:0,n:"That is chronic: dry cough, little phlegm, red tongue with little coat, thready rapid pulse. 肺陰虛乾咳少痰、舌紅少苔、脈細數。"}]}],
 teach:"Wind-cold and wind-heat both start on the exterior. The deciding signs are the balance of fever and chills, thirst, the colour of the phlegm and whether the pulse is tight or rapid.",
 teachZ:"風寒與風熱皆屬表證。分辨關鍵在寒熱孰重、口渴與否、痰之色質、脈之緊數。"},

{p:"肝陽上亢 Liver Yang Rising",tier:2,
 v:"A 45-year-old manager. Distending headache at both temples, dizziness, ringing ears. Flushed face, bitter taste in the mouth, irritable, sleeps badly. Everything worsens after arguments. Tongue: red, thin yellow coating. Pulse: wiry and rapid.",
 vz:"45歲主管。兩側太陽穴脹痛、頭暈耳鳴，面紅、口苦、急躁易怒、夜寐不安，爭執後加重。舌紅苔薄黃，脈弦數。",
 q:[{t:"Eight Principles — where and what nature?",z:"八綱：病位？病性？",
   o:[{a:"Interior · Heat 裡 · 熱",ok:1,n:"No chills, no floating pulse — this is <b>interior</b>; red face, bitter taste, red tongue, rapid pulse — <b>heat</b>. 無惡寒、脈不浮，屬裡；面紅口苦舌紅脈數，屬熱。"},
      {a:"Exterior · Heat 表 · 熱",ok:0,n:"Nothing here suggests an external pathogen on the surface. 無表證見症。"},
      {a:"Interior · Cold 裡 · 寒",ok:0,n:"Cold would bring pallor, aversion to cold, a slow pulse. 寒證見面白畏寒、脈遲。"}]},
  {t:"Which organ?",z:"病在何臟？",
   o:[{a:"Liver 肝",ok:1,n:"Temporal headache, wiry pulse, bitter taste, anger — the Liver's own signature. 頭側屬少陽肝膽，脈弦口苦易怒皆屬肝。"},
      {a:"Heart 心",ok:0,n:"Heart heat centres on palpitations, mouth ulcers, tongue-tip redness. 心火見心悸、口舌生瘡、舌尖紅。"},
      {a:"Lung 肺",ok:0,n:"No respiratory signs. 無肺系見症。"}]},
  {t:"Name the pattern.",z:"證型為何？",
   o:[{a:"肝陽上亢 Liver Yang rising",ok:1,n:"Correct — upper excess over lower deficiency, stirred by emotion. 上實下虛，因情志而動。"},
      {a:"肝血虛 Liver Blood deficiency",ok:0,n:"That gives pale tongue, blurred vision, numbness, a thready pulse — no heat. 肝血虛舌淡、視物昏花、肢麻、脈細，無熱象。"},
      {a:"肝鬱氣滯 Liver Qi stagnation",ok:0,n:"Stagnation alone brings distension and sighing without this much heat or rising. 氣滯以脹悶太息為主，熱象與上亢不著。"}]}],
 teach:"Wiry pulse + temporal headache + anger is the Liver triad. Then ask: is it merely stuck (stagnation), empty (blood deficiency), or rising (yang)?",
 teachZ:"脈弦＋頭側痛＋易怒為肝三聯。再問：是鬱（氣滯）、是虛（血虛）、還是亢（陽亢）。"},

{p:"脾氣虛 Spleen Qi Deficiency",tier:2,
 v:"A 38-year-old teacher, tired for months. Heaviest fatigue right after eating; bloating; loose unformed stools; poor appetite; speaks softly and dislikes talking. Tongue: pale, swollen with teeth marks, thin white coating. Pulse: weak and moderate.",
 vz:"38歲教師，倦怠數月。食後尤倦，脘腹脹滿，大便溏薄，納呆，語聲低微懶言。舌淡胖有齒痕、苔薄白，脈緩弱。",
 q:[{t:"Eight Principles.",z:"八綱辨證",
   o:[{a:"Interior · Deficiency 裡 · 虛",ok:1,n:"Months of illness, soft voice, weak pulse, teeth-marked tongue — <b>deficiency</b>, and <b>interior</b>. 久病、聲低、脈弱、齒痕舌，屬裡虛。"},
      {a:"Interior · Excess 裡 · 實",ok:0,n:"Excess would show a forceful pulse, a thick coating, distension that resists pressure. 實證脈有力、苔厚、拒按。"},
      {a:"Exterior · Deficiency 表 · 虛",ok:0,n:"Exterior deficiency (表虛) means spontaneous sweating with wind aversion — a surface pattern. 表虛指自汗惡風，屬表證。"}]},
  {t:"Which organ?",z:"病在何臟？",
   o:[{a:"Spleen 脾",ok:1,n:"The Spleen governs transformation and transportation and rules the four limbs; fatigue after eating is its calling card. 脾主運化、主四肢，食後倦甚為其特徵。"},
      {a:"Kidney 腎",ok:0,n:"Kidney deficiency centres on the low back, knees, urination and reproduction. 腎虛以腰膝、二便、生殖為主。"},
      {a:"Heart 心",ok:0,n:"No palpitations or sleep disturbance. 無心悸失眠。"}]},
  {t:"Name the pattern.",z:"證型為何？",
   o:[{a:"脾氣虛 Spleen Qi deficiency",ok:1,n:"Correct — the foundation pattern of Spleen weakness."},
      {a:"脾陽虛 Spleen Yang deficiency",ok:0,n:"That adds clear <b>cold</b>: cold limbs, cold abdominal pain relieved by warmth, watery stools. 脾陽虛更見畏寒肢冷、腹痛喜溫、便稀清冷。"},
      {a:"食積 Food stagnation",ok:0,n:"That is acute and excess: foul belching, thick greasy coat, aversion to food. 食積屬實，噯腐吞酸、苔厚膩、惡食。"}]}],
 teach:"Qi deficiency and Yang deficiency sit on the same line — Yang deficiency is Qi deficiency plus cold signs.",
 teachZ:"氣虛與陽虛在同一條線上——陽虛即氣虛再加寒象。"},

{p:"心脾兩虛 Heart and Spleen Deficiency",tier:4,
 v:"A 32-year-old accountant. Palpitations, difficulty falling asleep with many dreams, poor memory. Also tired, poor appetite, loose stools. Pale complexion and lips; periods scanty and pale. Tongue: pale, thin white coating. Pulse: thready and weak.",
 vz:"32歲會計。心悸、入睡難而多夢、健忘；兼倦怠納差便溏。面色與唇色淡白，月經量少色淡。舌淡苔薄白，脈細弱。",
 q:[{t:"Eight Principles.",z:"八綱辨證",
   o:[{a:"Interior · Deficiency 裡 · 虛",ok:1,n:"Pale everything, thready weak pulse, chronic course — <b>interior deficiency</b>. 面唇舌俱淡、脈細弱、病程久，屬裡虛。"},
      {a:"Interior · Heat · Excess 裡 · 熱 · 實",ok:0,n:"Nothing here is hot or forceful. 無熱象、無實象。"},
      {a:"Exterior · Cold 表 · 寒",ok:0,n:"No fever, chills or floating pulse. 無發熱惡寒、脈不浮。"}]},
  {t:"Which organs — note there may be two.",z:"病在何臟？（可能不只一個）",
   o:[{a:"Heart and Spleen 心與脾",ok:1,n:"Palpitations, dream-disturbed sleep and poor memory = <b>Heart</b> (blood fails to house the shen); fatigue, poor appetite, loose stools = <b>Spleen</b>. 心悸多夢健忘屬心（血不養神）；倦怠納差便溏屬脾。"},
      {a:"Heart and Kidney 心與腎",ok:0,n:"That pattern brings night sweats, five-centre heat, tinnitus and a red tongue — heat from Yin deficiency. 心腎不交見盜汗、五心煩熱、耳鳴、舌紅，屬陰虛內熱。"},
      {a:"Liver and Spleen 肝與脾",ok:0,n:"That would show distension, sighing, mood swings and a wiry pulse. 肝脾不和見脹滿太息、情志起伏、脈弦。"}]},
  {t:"Name the pattern.",z:"證型為何？",
   o:[{a:"心脾兩虛 Heart-Spleen deficiency",ok:1,n:"Correct. The Spleen is the source of blood production; when it is weak, the Heart is not nourished. 脾為氣血生化之源，脾虛則心失所養。"},
      {a:"心血虛 Heart Blood deficiency alone",ok:0,n:"That alone would not bring the appetite and stool signs. 單純心血虛無納差便溏。"},
      {a:"心陰虛 Heart Yin deficiency",ok:0,n:"That brings heat signs — night sweats, five-centre heat, red tongue. 心陰虛見盜汗、五心煩熱、舌紅。"}]}],
 teach:"When two organs appear together, look for the causal chain — here the Spleen fails to make blood, so the Heart loses its nourishment.",
 teachZ:"兩臟並見時，找出因果——此案為脾不生血，心失所養。"},

{p:"腎陽虛 Kidney Yang Deficiency",tier:2,
 v:"A 60-year-old man. Cold, sore, weak low back and knees; strongly averse to cold with cold limbs; passes urine three or four times a night, clear and copious; loose stools just before dawn. Tongue: pale and swollen, white coating. Pulse: deep, slow and weak, especially at the proximal position.",
 vz:"60歲男性。腰膝冷痛痠軟，畏寒肢冷，夜尿三四次、清長，黎明前泄瀉。舌淡胖苔白，脈沉遲無力，尺脈尤弱。",
 q:[{t:"Eight Principles.",z:"八綱辨證",
   o:[{a:"Interior · Cold · Deficiency 裡 · 寒 · 虛",ok:1,n:"Deep slow weak pulse, aversion to cold, clear copious urine — <b>interior cold deficiency</b>. 脈沉遲無力、畏寒、小便清長，屬裡寒虛。"},
      {a:"Interior · Cold · Excess 裡 · 寒 · 實",ok:0,n:"Cold excess brings sudden severe pain that resists pressure, with a tight forceful pulse. 實寒暴痛拒按、脈緊有力。"},
      {a:"Exterior · Cold 表 · 寒",ok:0,n:"No fever, no floating pulse, and this is chronic. 無發熱、脈不浮、病程久。"}]},
  {t:"Which organ?",z:"病在何臟？",
   o:[{a:"Kidney 腎",ok:1,n:"Low back is the house of the Kidney; nocturia and dawn diarrhoea point to Kidney Yang failing to warm. 腰為腎之府；夜尿、五更瀉為腎陽不溫。"},
      {a:"Spleen 脾",ok:0,n:"The Spleen is involved in the loose stools, but the low back, cold limbs and nocturia point deeper — to the root. 便溏雖關乎脾，然腰膝冷、夜尿多者，病本在腎。"},
      {a:"Bladder 膀胱",ok:0,n:"A Bladder pattern would be hot and urgent — burning, scanty, dark urine. 膀胱濕熱見尿頻急痛、色黃短少。"}]},
  {t:"Name the pattern.",z:"證型為何？",
   o:[{a:"腎陽虛 Kidney Yang deficiency",ok:1,n:"Correct — dawn diarrhoea (五更瀉) is its classic sign, because Kidney Yang fails to warm the Spleen. 五更瀉為典型，緣腎陽不能溫煦脾土。"},
      {a:"腎陰虛 Kidney Yin deficiency",ok:0,n:"That is hot and dry: night sweats, five-centre heat, red tongue with little coat, thready rapid pulse. 腎陰虛見盜汗、五心煩熱、舌紅少苔、脈細數。"},
      {a:"脾陽虛 Spleen Yang deficiency",ok:0,n:"Closer — but the low back, knees and nocturia mark the Kidney as the root. 近似，然腰膝與夜尿標示病本在腎。"}]}],
 teach:"Yin deficiency and Yang deficiency are both deficiency — the difference is whether heat or cold appears alongside.",
 teachZ:"陰虛陽虛皆屬虛，分別在於兼熱象或兼寒象。"},

{p:"肝鬱氣滯 Liver Qi Stagnation",tier:2,
 v:"A 28-year-old designer. Fullness and distension in the chest and under the ribs, frequent sighing, a lump-in-the-throat sensation. Mood swings; breasts distend before periods; symptoms come and go with her mood rather than with meals or weather. Tongue: normal, thin white coating. Pulse: wiry.",
 vz:"28歲設計師。胸脅脹滿、時時太息、咽中如有物梗。情緒起伏，經前乳脹；症狀隨情志而增減，與飲食天氣無關。舌淡紅苔薄白，脈弦。",
 q:[{t:"Eight Principles.",z:"八綱辨證",
   o:[{a:"Interior · Excess 裡 · 實",ok:1,n:"A wiry pulse with distension that shifts is <b>qi stagnation</b> — an excess pattern, interior. 脈弦、脹滿走竄，屬氣滯實證，病在裡。"},
      {a:"Interior · Deficiency 裡 · 虛",ok:0,n:"Deficiency brings a weak pulse and constant, dull, better-with-pressure discomfort. 虛證脈弱、隱痛喜按。"},
      {a:"Exterior · Excess 表 · 實",ok:0,n:"No exterior signs at all. 無表證。"}]},
  {t:"Which organ?",z:"病在何臟？",
   o:[{a:"Liver 肝",ok:1,n:"The Liver governs the free flow of qi and its channel passes the chest and ribs; emotion is its trigger. 肝主疏泄，其經布脅肋，情志為誘因。"},
      {a:"Lung 肺",ok:0,n:"The Lung governs qi too, but would present with cough and breathing changes. 肺雖主氣，然當見咳喘。"},
      {a:"Spleen 脾",ok:0,n:"Spleen distension follows meals, not moods. 脾脹隨飲食，不隨情志。"}]},
  {t:"Name the pattern.",z:"證型為何？",
   o:[{a:"肝鬱氣滯 Liver Qi stagnation",ok:1,n:"Correct — the globus sensation (梅核氣) belongs to this family too."},
      {a:"肝火上炎 Liver Fire flaring",ok:0,n:"Fire would add red eyes, bitter taste, a rapid pulse and a yellow coat. 肝火見目赤口苦、脈數、苔黃。"},
      {a:"肝血虛 Liver Blood deficiency",ok:0,n:"That gives pale tongue, blurred vision, thready pulse. 肝血虛舌淡、視昏、脈細。"}]}],
 teach:"Ask what makes it better or worse. Emotion-linked distension is Liver; meal-linked is Spleen or Stomach; weather-linked often points to an external factor.",
 teachZ:"問其加重緩解之由：隨情志者在肝，隨飲食者在脾胃，隨天氣者多關外邪。"},

{p:"膀胱濕熱 Damp-Heat in the Bladder",tier:2,
 v:"A 26-year-old woman, ill three days. Urination frequent, urgent and burning; urine scanty, dark and turbid; discomfort low in the abdomen; slight fever. Tongue: red with a yellow greasy coating. Pulse: slippery and rapid.",
 vz:"26歲女性，病起三日。小便頻急灼痛，尿短赤混濁，小腹不適，微發熱。舌紅苔黃膩，脈滑數。",
 q:[{t:"Eight Principles.",z:"八綱辨證",
   o:[{a:"Interior · Heat · Excess 裡 · 熱 · 實",ok:1,n:"Burning, dark scanty urine, yellow greasy coat, slippery rapid pulse — <b>interior damp-heat, excess</b>. 灼痛尿赤、苔黃膩、脈滑數，屬裡濕熱實證。"},
      {a:"Interior · Cold · Deficiency 裡 · 寒 · 虛",ok:0,n:"Cold deficiency gives clear copious urine and a deep slow pulse. 虛寒者小便清長、脈沉遲。"},
      {a:"Exterior · Heat 表 · 熱",ok:0,n:"The pulse is not floating and the problem is clearly in the lower burner. 脈不浮，病位在下焦。"}]},
  {t:"Where is it?",z:"病位何在？",
   o:[{a:"Bladder 膀胱",ok:1,n:"The Bladder stores and discharges urine; damp-heat pouring down disturbs its qi transformation. 膀胱貯尿排尿，濕熱下注則氣化不利。"},
      {a:"Kidney 腎",ok:0,n:"Kidney patterns are chronic and deficient — low back, nocturia, weak pulse. 腎病多虛多久，見腰膝、夜尿、脈弱。"},
      {a:"Large Intestine 大腸",ok:0,n:"That would present with stool changes, not urination. 大腸病當見大便異常。"}]},
  {t:"Name the pattern.",z:"證型為何？",
   o:[{a:"膀胱濕熱 Damp-Heat in the Bladder",ok:1,n:"Correct — the greasy coating is what marks the <b>damp</b> alongside the heat. 苔膩正是濕之標誌。"},
      {a:"心火下移小腸 Heart Fire shifting to the Small Intestine",ok:0,n:"That version adds mouth ulcers, irritability and a red tongue tip. 此證兼口舌生瘡、心煩、舌尖紅。"},
      {a:"腎陰虛 Kidney Yin deficiency",ok:0,n:"Chronic, with night sweats and a thready rapid pulse — not an acute burning. 腎陰虛久病盜汗脈細數，非急性灼痛。"}]}],
 teach:"A greasy coating is the single most reliable sign of dampness. Heat plus greasy coat plus a slippery pulse = damp-heat.",
 teachZ:"苔膩是辨濕最可靠之徵。熱象＋膩苔＋脈滑＝濕熱。"},

{p:"心腎不交 Heart and Kidney Not Communicating",tier:4,
 v:"A 50-year-old woman. Cannot fall asleep, mind racing at night; palpitations; night sweats; heat in the palms, soles and chest; ringing ears and sore weak low back. Tongue: red with little coating. Pulse: thready and rapid.",
 vz:"50歲女性。難以入睡、夜間心煩思緒紛擾，心悸、盜汗，五心煩熱，耳鳴、腰膝痠軟。舌紅少苔，脈細數。",
 q:[{t:"Eight Principles.",z:"八綱辨證",
   o:[{a:"Interior · Heat · Deficiency 裡 · 熱 · 虛",ok:1,n:"Heat signs on a thready pulse with little tongue coating = <b>deficiency heat</b> from Yin deficiency. 熱象而脈細舌少苔，屬陰虛內熱。"},
      {a:"Interior · Heat · Excess 裡 · 熱 · 實",ok:0,n:"Excess heat gives a forceful rapid pulse, thick yellow coat, high fever or strong thirst. 實熱脈數有力、苔黃厚、壯熱口渴。"},
      {a:"Interior · Cold · Deficiency 裡 · 寒 · 虛",ok:0,n:"No cold signs are present. 無寒象。"}]},
  {t:"Which organs?",z:"病在何臟？",
   o:[{a:"Heart and Kidney 心與腎",ok:1,n:"Insomnia and palpitations = <b>Heart</b>; tinnitus, sore low back and night sweats = <b>Kidney</b> Yin. 失眠心悸屬心；耳鳴腰痠盜汗屬腎陰。"},
      {a:"Heart and Spleen 心與脾",ok:0,n:"That pattern is pale and tired without heat — appetite and stool signs dominate. 心脾兩虛面淡無熱，以納差便溏為主。"},
      {a:"Liver and Gallbladder 肝與膽",ok:0,n:"That would bring a wiry pulse, bitter taste and hypochondriac signs. 肝膽證見脈弦、口苦、脅痛。"}]},
  {t:"Name the pattern.",z:"證型為何？",
   o:[{a:"心腎不交 Heart and Kidney not communicating",ok:1,n:"Correct — Kidney water fails to rise and restrain Heart fire, so the shen will not settle at night. 腎水不能上濟心火，心神不安於夜。"},
      {a:"心脾兩虛 Heart-Spleen deficiency",ok:0,n:"No heat, no tinnitus, no back soreness in that pattern. 心脾兩虛無熱象、無耳鳴腰痠。"},
      {a:"痰熱擾心 Phlegm-Heat harassing the Heart",ok:0,n:"That brings a greasy yellow coat, a slippery rapid pulse, heavy chest and agitation. 痰熱擾心苔黃膩、脈滑數、胸悶煩躁。"}]}],
 teach:"Deficiency heat and excess heat both look hot. The pulse (thready vs forceful) and the tongue coating (scanty vs thick) separate them.",
 teachZ:"虛熱實熱皆見熱象，分辨在脈之細與有力、苔之少與厚。"},
{p:"胃陰虛 Stomach Yin Deficiency",tier:3,
 v:"A 54-year-old man, months of trouble. Hungry but cannot eat much; dry mouth and throat, worse in the afternoon; dull burning discomfort in the upper abdomen; dry stools. Tongue: red, cracked, almost no coating. Pulse: thready and rapid.",
 vz:"54歲男性，病延數月。飢而不欲食，口乾咽燥午後尤甚，胃脘隱隱灼痛，大便乾結。舌紅有裂紋、幾無苔，脈細數。",
 q:[{t:"Eight Principles.",z:"八綱辨證",
   o:[{a:"Interior · Heat · Deficiency 裡 · 熱 · 虛",ok:1,n:"Heat signs on a <b>thready</b> pulse with a <b>peeled</b> tongue = deficiency heat. 熱象而脈細、舌少苔，屬虛熱。"},
      {a:"Interior · Heat · Excess 裡 · 熱 · 實",ok:0,n:"Excess stomach heat brings strong hunger, foul breath, a thick yellow coat and a forceful pulse. 胃實熱消穀善飢、口臭、苔黃厚、脈有力。"},
      {a:"Interior · Cold · Deficiency 裡 · 寒 · 虛",ok:0,n:"No cold signs; the tongue is red, not pale. 無寒象，舌紅非淡。"}]},
  {t:"Which organ?",z:"病在何臟腑？",
   o:[{a:"Stomach 胃",ok:1,n:"Hunger without appetite and epigastric burning point to the Stomach; the Stomach likes moisture. 飢不欲食、胃脘灼痛在胃；胃喜潤惡燥。"},
      {a:"Spleen 脾",ok:0,n:"Spleen deficiency gives a pale swollen tongue, loose stools and fatigue — not dryness. 脾虛舌淡胖、便溏、倦怠，非燥象。"},
      {a:"Liver 肝",ok:0,n:"No wiry pulse or hypochondriac signs. 無脈弦脅痛。"}]},
  {t:"Name the pattern.",z:"證型為何？",
   o:[{a:"胃陰虛 Stomach Yin deficiency",ok:1,n:"Correct — the cracked, peeled tongue is the giveaway. 舌紅裂少苔為其標誌。"},
      {a:"胃火熾盛 Blazing Stomach Fire",ok:0,n:"That is excess: burning pain, foul breath, bleeding gums, thick yellow coat. 胃火屬實：灼痛、口臭、齒衄、苔黃厚。"},
      {a:"食滯胃脘 Food stagnation",ok:0,n:"Acute, with belching of sour food and a greasy coat. 食滯噯腐吞酸、苔厚膩，屬新病。"}]}],
 teach:"A peeled or cracked tongue with little coating is the most reliable sign that Yin — and the fluids — have been consumed.",
 teachZ:"舌少苔、有裂紋，是陰液耗傷最可靠的徵象。"},

{p:"痰濕阻肺 Phlegm-Damp obstructing the Lung",tier:3,
 v:"A 58-year-old smoker. Cough for years, worse in the morning; copious white sticky phlegm, easy to expectorate; chest feels heavy and full; body feels heavy; appetite poor. Tongue: pale with a white greasy coating. Pulse: slippery.",
 vz:"58歲吸菸者。咳嗽多年，晨起尤甚，痰多白黏易咳出，胸悶身重，納呆。舌淡苔白膩，脈滑。",
 q:[{t:"Eight Principles.",z:"八綱辨證",
   o:[{a:"Interior · Excess (with deficiency) 裡 · 實（本虛標實）",ok:1,n:"The greasy coat and slippery pulse mark a substantial pathogen — phlegm — sitting on a weak Spleen. 苔膩脈滑為有形之邪（痰），本於脾虛。"},
      {a:"Exterior · Cold 表 · 寒",ok:0,n:"Years of illness with no fever or floating pulse is not exterior. 病久無發熱、脈不浮，非表證。"},
      {a:"Interior · Heat · Excess 裡 · 熱 · 實",ok:0,n:"Heat would give yellow sticky phlegm, thirst and a rapid pulse. 熱則痰黃稠、口渴、脈數。"}]},
  {t:"Which organs?",z:"病在何臟？",
   o:[{a:"Lung and Spleen 肺與脾",ok:1,n:"\"The Spleen is the source of phlegm, the Lung is the container that stores it.\" 「脾為生痰之源，肺為貯痰之器。」"},
      {a:"Lung and Kidney 肺與腎",ok:0,n:"That combination shows in chronic wheezing with low-back weakness — failure to grasp qi. 肺腎同病見久喘、腰膝無力，屬腎不納氣。"},
      {a:"Heart and Lung 心與肺",ok:0,n:"That would bring palpitations and blue lips. 心肺同病見心悸唇紫。"}]},
  {t:"Name the pattern.",z:"證型為何？",
   o:[{a:"痰濕阻肺 Phlegm-Damp obstructing the Lung",ok:1,n:"Correct — treat the Lung for the branch, the Spleen for the root. 治肺為標，治脾為本。"},
      {a:"風寒犯肺 Wind-Cold invading the Lung",ok:0,n:"That is acute with chills, no sweating and a tight pulse. 風寒新病惡寒無汗、脈緊。"},
      {a:"肺陰虛 Lung Yin deficiency",ok:0,n:"That is a dry cough with scanty phlegm and a peeled red tongue. 肺陰虛乾咳少痰、舌紅少苔。"}]}],
 teach:"Whenever you see a greasy coating and a slippery pulse together, think substance: phlegm or damp, not merely qi.",
 teachZ:"見膩苔配滑脈，即當想到有形之邪——痰或濕，而非單純氣分之病。"},

{p:"血瘀 Blood Stasis",tier:3,
 v:"A 47-year-old woman. Fixed, stabbing pain in the lower abdomen that is worse at night and worse with pressure; periods come with dark clots, and the pain eases once the clots pass. Complexion dull and dark; lips purple. Tongue: purple with stasis spots, veins beneath it distended. Pulse: choppy.",
 vz:"47歲女性。少腹刺痛固定不移，夜間及按壓加重；經行血塊色暗，塊下痛減。面色晦暗，唇紫。舌紫暗有瘀點、舌下絡脈怒張，脈澀。",
 q:[{t:"Eight Principles.",z:"八綱辨證",
   o:[{a:"Interior · Excess 裡 · 實",ok:1,n:"Pain that <b>resists pressure</b> and a fixed location = an excess, substantial obstruction. 痛而拒按、固定不移，屬實、屬有形之阻。"},
      {a:"Interior · Deficiency 裡 · 虛",ok:0,n:"Deficiency pain is dull and <b>likes</b> pressure and warmth. 虛痛隱隱喜按喜溫。"},
      {a:"Exterior · Excess 表 · 實",ok:0,n:"No exterior signs. 無表證。"}]},
  {t:"What is the pathogen?",z:"病邪為何？",
   o:[{a:"Blood stasis 瘀血",ok:1,n:"Stabbing, fixed, night-worse pain with a purple tongue and choppy pulse — the four classic marks. 刺痛、固定、夜甚，舌紫脈澀，四大特徵俱全。"},
      {a:"Qi stagnation 氣滯",ok:0,n:"Qi pain wanders and distends and shifts with mood; the tongue is not purple. 氣滯痛脹走竄、隨情志變化，舌不紫。"},
      {a:"Cold accumulation 寒凝",ok:0,n:"Cold pain is relieved by warmth and comes with a tight pulse — though cold often causes stasis. 寒痛得溫則減、脈緊；然寒凝常致血瘀。"}]},
  {t:"Name the pattern.",z:"證型為何？",
   o:[{a:"血瘀 Blood stasis",ok:1,n:"Correct. Ask always what caused it — qi stagnation, cold, heat, trauma or deficiency. 正確。再問其因：氣滯、寒、熱、外傷或虛。"},
      {a:"氣血兩虛 Qi and Blood deficiency",ok:0,n:"That is pale and weak, with pain that likes pressure. 氣血兩虛面淡體弱、痛而喜按。"},
      {a:"濕熱下注 Damp-Heat pouring down",ok:0,n:"That brings burning, discharge, a yellow greasy coat and a slippery rapid pulse. 濕熱見灼熱、帶下、苔黃膩、脈滑數。"}]}],
 teach:"Four signs name blood stasis: stabbing pain, fixed location, worse at night, purple tongue with a choppy pulse.",
 teachZ:"辨瘀血四徵：刺痛、固定、夜甚、舌紫脈澀。"},

{p:"氣血兩虛 Qi and Blood Deficiency",tier:3,
 v:"A 35-year-old new mother. Constant tiredness, breathless on slight exertion, sweats without effort; dizzy when standing up, blurred vision, numb fingertips; pale face and lips, brittle nails. Tongue: pale, thin white coating. Pulse: thready and weak.",
 vz:"35歲產後婦女。倦怠乏力，動則氣促自汗；起身頭暈、視物昏花、指尖發麻；面唇色淡，爪甲不榮。舌淡苔薄白，脈細弱。",
 q:[{t:"Eight Principles.",z:"八綱辨證",
   o:[{a:"Interior · Deficiency 裡 · 虛",ok:1,n:"Everything is pale, weak and worse with exertion — classic deficiency. 面舌俱淡、脈弱、動則加重，屬虛。"},
      {a:"Interior · Excess 裡 · 實",ok:0,n:"Nothing forceful or obstructing here. 無實象。"},
      {a:"Exterior · Deficiency 表 · 虛",ok:0,n:"Exterior deficiency means sweating with aversion to wind, an exterior pattern. 表虛指自汗惡風，屬表證。"}]},
  {t:"Which is deficient — qi, blood, or both?",z:"氣虛？血虛？抑或兩虛？",
   o:[{a:"Both qi and blood 氣血兩虛",ok:1,n:"Breathlessness and spontaneous sweat = <b>qi</b>; dizziness, blurred vision, numbness, pale lips and nails = <b>blood</b>. 氣促自汗屬氣虛；眩暈視昏、肢麻、唇甲不榮屬血虛。"},
      {a:"Qi only 單純氣虛",ok:0,n:"Qi deficiency alone does not bring numbness, blurred vision or pale lips and nails. 單純氣虛無肢麻、視昏、唇甲不榮。"},
      {a:"Blood only 單純血虛",ok:0,n:"Blood deficiency alone does not bring breathlessness and spontaneous sweating. 單純血虛無氣促自汗。"}]},
  {t:"Name the pattern.",z:"證型為何？",
   o:[{a:"氣血兩虛 Qi and Blood deficiency",ok:1,n:"Correct — very common after childbirth, prolonged illness or blood loss. 產後、久病、失血後最為常見。"},
      {a:"心脾兩虛 Heart-Spleen deficiency",ok:0,n:"Close family — but that pattern leads with palpitations, insomnia and poor appetite. 近似，然心脾兩虛以心悸失眠納差為主。"},
      {a:"腎陰虛 Kidney Yin deficiency",ok:0,n:"That brings heat: night sweats, five-centre heat, red tongue. 腎陰虛見盜汗、五心煩熱、舌紅。"}]}],
 teach:"Qi and blood support each other — qi moves blood, blood carries qi. After blood loss, expect both to be short.",
 teachZ:"氣血相依：氣為血帥，血為氣母。失血之後，兩者多同時虧虛。"},

{p:"寒濕困脾 Cold-Damp encumbering the Spleen",tier:3,
 v:"A 30-year-old chef, worse in the rainy season. Heavy fullness in the upper abdomen with no appetite; head feels wrapped in cloth; limbs heavy; sticky loose stools; no thirst, mouth feels bland and sticky. Tongue: pale swollen, white greasy coating. Pulse: soft and moderate.",
 vz:"30歲廚師，梅雨季加重。脘腹痞悶納呆，頭重如裹，肢體困重，大便黏溏，口淡不渴、口中黏膩。舌淡胖苔白膩，脈濡緩。",
 q:[{t:"Eight Principles.",z:"八綱辨證",
   o:[{a:"Interior · Cold · Excess 裡 · 寒 · 實",ok:1,n:"A white <b>greasy</b> coating with no thirst = cold damp, a substantial pathogen. 苔白膩、口淡不渴，為寒濕有形之邪。"},
      {a:"Interior · Heat · Excess 裡 · 熱 · 實",ok:0,n:"Heat would give a yellow greasy coat, thirst and a rapid pulse. 熱則苔黃膩、口渴、脈數。"},
      {a:"Interior · Deficiency 裡 · 虛",ok:0,n:"Pure deficiency would not show a greasy coating. 純虛證不見膩苔。"}]},
  {t:"Which organ is encumbered?",z:"何臟被困？",
   o:[{a:"Spleen 脾",ok:1,n:"The Spleen dislikes damp; when damp encumbers it, transformation stops — hence fullness, heaviness and sticky stools. 脾惡濕，濕困則運化失司，故痞悶、身重、便黏。"},
      {a:"Kidney 腎",ok:0,n:"No low-back, urinary or cold-limb signs of the root. 無腰膝、二便、肢冷等腎候。"},
      {a:"Lung 肺",ok:0,n:"No cough or breathing signs. 無咳喘。"}]},
  {t:"Name the pattern.",z:"證型為何？",
   o:[{a:"寒濕困脾 Cold-Damp encumbering the Spleen",ok:1,n:"Correct — an excess pattern, unlike Spleen qi deficiency which is empty. 屬實證，與脾氣虛之虛證不同。"},
      {a:"脾氣虛 Spleen Qi deficiency",ok:0,n:"That is empty and thin-coated, worse after eating rather than with the weather. 脾氣虛苔薄、食後加重，非隨天氣。"},
      {a:"濕熱蘊脾 Damp-Heat in the Spleen",ok:0,n:"That version is thirsty-but-not-drinking, bitter mouth, yellow greasy coat. 濕熱蘊脾見口渴不欲飲、口苦、苔黃膩。"}]}],
 teach:"Damp is heavy, sticky, lingering and worse in wet weather. Cold damp has a white coat; damp-heat a yellow one.",
 teachZ:"濕性重濁黏滯，逢陰雨加重。寒濕苔白，濕熱苔黃。"},

{p:"肝火上炎 Liver Fire Flaring Upward",tier:2,
 v:"A 41-year-old man after a week of conflict at work. Splitting headache, red painful eyes, ringing ears that came on suddenly and loudly; bitter taste, dry mouth; furious temper; constipation, dark urine. Tongue: red at the edges, yellow coating. Pulse: wiry and rapid, forceful.",
 vz:"41歲男性，職場衝突一週後。頭痛劇烈、目赤腫痛、耳鳴暴響，口苦咽乾，暴躁易怒，便秘尿黃。舌邊紅苔黃，脈弦數有力。",
 q:[{t:"Eight Principles.",z:"八綱辨證",
   o:[{a:"Interior · Heat · Excess 裡 · 熱 · 實",ok:1,n:"A <b>forceful</b> rapid pulse with a yellow coat and constipation = excess heat. 脈數有力、苔黃、便秘，屬實熱。"},
      {a:"Interior · Heat · Deficiency 裡 · 熱 · 虛",ok:0,n:"Deficiency heat is thready, with night sweats and a peeled tongue. 虛熱脈細、盜汗、舌少苔。"},
      {a:"Exterior · Heat 表 · 熱",ok:0,n:"No fever, chills or floating pulse. 無發熱惡寒、脈不浮。"}]},
  {t:"Which organ?",z:"病在何臟？",
   o:[{a:"Liver 肝",ok:1,n:"The Liver opens to the eyes; its channel reaches the ear and the vertex. Red eyes, sudden loud tinnitus, bitter taste, rage. 肝開竅於目，其經上耳達巔。目赤、暴鳴、口苦、暴怒。"},
      {a:"Heart 心",ok:0,n:"Heart fire centres on the tongue tip, mouth ulcers and palpitations. 心火見舌尖紅、口舌生瘡、心悸。"},
      {a:"Stomach 胃",ok:0,n:"Stomach fire brings bleeding gums, foul breath and strong hunger. 胃火見齒衄、口臭、消穀善飢。"}]},
  {t:"Fire or rising Yang? Name the pattern.",z:"是火還是陽亢？證型為何？",
   o:[{a:"肝火上炎 Liver Fire flaring",ok:1,n:"Correct — pure <b>excess</b>: sudden, loud, forceful pulse, constipation. 純實證：起病急、聲響大、脈有力、便秘。"},
      {a:"肝陽上亢 Liver Yang rising",ok:0,n:"That is excess above on deficiency below: dizziness, weak low back and knees, a wiry but not forceful pulse. 肝陽上亢上實下虛，見眩暈、腰膝痠軟、脈弦而不甚有力。"},
      {a:"肝鬱氣滯 Liver Qi stagnation",ok:0,n:"Stagnation alone has no heat and no forceful pulse. 氣滯無熱象、脈不數不有力。"}]}],
 teach:"Liver Fire and rising Liver Yang share the Liver's route. Fire is loud, sudden, forceful and excess; rising Yang stands on an empty foundation below.",
 teachZ:"肝火與肝陽同循肝經。火者急、響、有力，屬實；陽亢者下有虛本。"},

{p:"風寒犯肺 Wind-Cold invading the Lung",tier:5,pair:"風熱犯肺",
 v:"A 30-year-old courier, ill since being caught in cold rain yesterday. Chills much stronger than the fever; no sweating at all; cough with thin white phlegm; stiff aching neck and shoulders; no thirst. Tongue: pale-red, thin white coating. Pulse: floating and tight.",
 vz:"30歲快遞員，昨日淋冷雨後起病。惡寒重、發熱輕，全無汗出，咳吐稀白痰，項背強痛，口不渴。舌淡紅苔薄白，脈浮緊。",
 q:[{t:"Eight Principles.",z:"八綱辨證",
   o:[{a:"Exterior · Cold · Excess 表 · 寒 · 實",ok:1,n:"One day old, floating pulse, chills>fever, <b>no sweat</b> — exterior cold excess. 新病脈浮、惡寒重、無汗，屬表寒實。"},
      {a:"Exterior · Heat · Excess 表 · 熱 · 實",ok:0,n:"Wind-heat gives sore throat, thirst, yellow phlegm and a <b>rapid</b> pulse. 風熱見咽痛、口渴、痰黃、脈數。"},
      {a:"Exterior · Cold · Deficiency 表 · 寒 · 虛",ok:0,n:"Exterior deficiency <b>sweats</b> and dislikes wind; this patient has no sweat at all. 表虛有汗惡風，本案全無汗。"}]},
  {t:"Which organ?",z:"病在何臟？",
   o:[{a:"Lung 肺",ok:1,n:"Cough and phlegm; the Lung rules the exterior through the skin and body hair. 咳痰在肺；肺外合皮毛，主一身之表。"},
      {a:"Bladder 膀胱",ok:0,n:"The Taiyang channel explains the stiff neck, but the cough places the illness in the Lung. 項強屬太陽經，然咳嗽定位在肺。"},
      {a:"Spleen 脾",ok:0,n:"No appetite or stool signs. 無納差便溏。"}]},
  {t:"Wind-Cold or Wind-Heat?",z:"風寒？風熱？",
   o:[{a:"風寒犯肺 Wind-Cold invading the Lung",ok:1,n:"Correct. The deciders: chills>fever, <b>no sweat</b>, thin white phlegm, no thirst, tight pulse. 判準：惡寒重、無汗、痰稀白、不渴、脈緊。"},
      {a:"風熱犯肺 Wind-Heat invading the Lung",ok:0,n:"Everything here is cold. Wind-heat runs hot: sore throat, thirst, yellow phlegm, rapid pulse. 本案全屬寒；風熱見咽痛口渴痰黃脈數。"},
      {a:"燥邪犯肺 Dryness attacking the Lung",ok:0,n:"Dryness gives a dry cough with scanty phlegm, dry nose and throat, usually in autumn. 燥邪乾咳少痰、鼻咽乾燥，多見於秋。"}]}],
 teach:"Wind-cold and wind-heat is the first differential every student meets. Sweat, thirst, phlegm colour and pulse quality decide it — not the season.",
 teachZ:"風寒與風熱是初學第一組鑑別。判準在汗、渴、痰色、脈象，而非季節。"},

{p:"脾陽虛 Spleen Yang Deficiency",tier:5,pair:"脾氣虛",
 v:"A 44-year-old market trader. Long-standing fatigue and bloating, but now also: dull abdominal pain that is <em>better with warmth and pressure</em>, cold hands and feet, watery stools with undigested food, no thirst. Tongue: pale swollen, white slippery coating. Pulse: deep, slow and weak.",
 vz:"44歲攤商。倦怠腹脹已久，今更見腹部隱痛、喜溫喜按，手足不溫，大便清稀完穀不化，口不渴。舌淡胖苔白滑，脈沉遲無力。",
 q:[{t:"Eight Principles.",z:"八綱辨證",
   o:[{a:"Interior · Cold · Deficiency 裡 · 寒 · 虛",ok:1,n:"Pain that <b>likes warmth and pressure</b> plus a deep slow weak pulse = deficiency cold. 痛而喜溫喜按、脈沉遲無力，屬虛寒。"},
      {a:"Interior · Cold · Excess 裡 · 寒 · 實",ok:0,n:"Excess cold is sudden, severe and <b>resists</b> pressure. 實寒暴痛拒按。"},
      {a:"Interior · Heat · Deficiency 裡 · 熱 · 虛",ok:0,n:"No heat at all — the tongue is pale, not red. 全無熱象，舌淡非紅。"}]},
  {t:"Which organ?",z:"病在何臟？",
   o:[{a:"Spleen 脾",ok:1,n:"Bloating, undigested food in the stool, fatigue — transformation and transportation have failed. 腹脹、完穀不化、倦怠，運化失司。"},
      {a:"Kidney 腎",ok:0,n:"Kidney Yang deficiency leads with a cold sore low back, nocturia and dawn diarrhoea. 腎陽虛以腰膝冷、夜尿、五更瀉為主。"},
      {a:"Liver 肝",ok:0,n:"No wiry pulse or emotional trigger. 無脈弦、無情志誘因。"}]},
  {t:"Qi deficiency or Yang deficiency?",z:"氣虛？陽虛？",
   o:[{a:"脾陽虛 Spleen Yang deficiency",ok:1,n:"Correct — Spleen qi deficiency <b>plus cold signs</b>: cold limbs, pain better with warmth, watery stools, slippery white coat. 即脾氣虛再加寒象：肢冷、得溫痛減、便清稀、苔白滑。"},
      {a:"脾氣虛 Spleen Qi deficiency",ok:0,n:"Qi deficiency alone is tired and bloated but <b>not cold</b>. 單純脾氣虛倦怠腹脹，然無寒象。"},
      {a:"寒濕困脾 Cold-Damp encumbering the Spleen",ok:0,n:"That is an <b>excess</b> pattern with a greasy coat and heaviness, worse in wet weather. 寒濕困脾屬實，苔膩身重，遇陰雨加重。"}]}],
 teach:"Qi deficiency, Yang deficiency, and cold-damp look alike at a glance. Ask two questions: is there cold, and is it empty or full?",
 teachZ:"氣虛、陽虛、寒濕乍看相似。只問兩句：有無寒象？是虛是實？"},

{p:"腎陰虛 Kidney Yin Deficiency",tier:5,pair:"腎陽虛",
 v:"A 55-year-old teacher. Sore weak low back and knees, ringing ears, dizziness; night sweats and heat in the palms, soles and chest; dry mouth at night; scanty dark urine; constipation. Tongue: red with little coating. Pulse: thready and rapid.",
 vz:"55歲教師。腰膝痠軟、耳鳴眩暈，盜汗、五心煩熱，夜間口乾，小便短赤，大便乾結。舌紅少苔，脈細數。",
 q:[{t:"Eight Principles.",z:"八綱辨證",
   o:[{a:"Interior · Heat · Deficiency 裡 · 熱 · 虛",ok:1,n:"Heat on a <b>thready</b> pulse with a peeled tongue = deficiency heat. 熱象而脈細、舌少苔，屬虛熱。"},
      {a:"Interior · Cold · Deficiency 裡 · 寒 · 虛",ok:0,n:"That is the Yang-deficient twin: cold limbs, clear copious urine, deep slow pulse. 此為陽虛之對照：肢冷、尿清長、脈沉遲。"},
      {a:"Interior · Heat · Excess 裡 · 熱 · 實",ok:0,n:"Excess heat is forceful, with a thick yellow coat and high fever or strong thirst. 實熱脈有力、苔黃厚、壯熱口渴。"}]},
  {t:"Which organ?",z:"病在何臟？",
   o:[{a:"Kidney 腎",ok:1,n:"Low back and knees, ears and hearing, bones and marrow — all Kidney territory. 腰膝、耳竅、骨髓，皆屬腎。"},
      {a:"Heart 心",ok:0,n:"Heart Yin deficiency leads with palpitations and insomnia. 心陰虛以心悸失眠為主。"},
      {a:"Liver 肝",ok:0,n:"Liver Yin deficiency brings dry eyes, blurred vision and hypochondriac ache. 肝陰虛見目乾視昏、脅隱痛。"}]},
  {t:"Yin or Yang deficiency?",z:"陰虛？陽虛？",
   o:[{a:"腎陰虛 Kidney Yin deficiency",ok:1,n:"Correct. Same location, opposite nature: heat, dryness, night sweats, red peeled tongue, thready rapid pulse. 部位相同、性質相反：熱、燥、盜汗、舌紅少苔、脈細數。"},
      {a:"腎陽虛 Kidney Yang deficiency",ok:0,n:"That is cold: aversion to cold, nocturia, dawn diarrhoea, pale swollen tongue, deep slow pulse. 腎陽虛屬寒：畏寒、夜尿、五更瀉、舌淡胖、脈沉遲。"},
      {a:"腎精不足 Kidney Essence insufficiency",ok:0,n:"That shows as slow development, early greying, poor memory and weak bones — without marked heat. 腎精不足見發育遲、早白、健忘、骨弱，熱象不著。"}]}],
 teach:"Yin and Yang deficiency of the same organ share the location and split on temperature. Learn the pair together and neither can trick you.",
 teachZ:"同一臟之陰虛陽虛，部位相同、寒熱相反。成對記憶，兩者皆難相欺。"},

{p:"胃火熾盛 Blazing Stomach Fire",tier:5,pair:"胃陰虛",
 v:"A 36-year-old chef. Burning pain in the upper abdomen; ravenous hunger, eats a great deal and is soon hungry again; foul breath; swollen painful bleeding gums; strong thirst for cold drinks; constipation. Tongue: red with a thick yellow coating. Pulse: slippery, rapid and forceful.",
 vz:"36歲廚師。胃脘灼痛，消穀善飢、食後易飢，口臭，齒齦腫痛出血，口渴喜冷飲，大便秘結。舌紅苔黃厚，脈滑數有力。",
 q:[{t:"Eight Principles.",z:"八綱辨證",
   o:[{a:"Interior · Heat · Excess 裡 · 熱 · 實",ok:1,n:"A <b>forceful</b> rapid pulse with a thick yellow coat and constipation = excess fire. 脈數有力、苔黃厚、便秘，屬實火。"},
      {a:"Interior · Heat · Deficiency 裡 · 熱 · 虛",ok:0,n:"Deficiency heat is thready with a <b>peeled</b> tongue and afternoon flushes. 虛熱脈細、舌少苔、午後潮熱。"},
      {a:"Interior · Cold · Excess 裡 · 寒 · 實",ok:0,n:"No cold signs. 無寒象。"}]},
  {t:"Which organ?",z:"病在何腑？",
   o:[{a:"Stomach 胃",ok:1,n:"The Stomach channel wraps the gums; fire there burns the gums and grinds through food. 足陽明胃經入齒齦；胃火則齦腫、消穀。"},
      {a:"Large Intestine 大腸",ok:0,n:"Constipation is shared, but the gums and hunger point to the Stomach. 便秘雖同，然齒齦與善飢定位在胃。"},
      {a:"Liver 肝",ok:0,n:"Liver fire brings red eyes, bitter taste and a wiry pulse. 肝火見目赤口苦脈弦。"}]},
  {t:"Fire or Yin deficiency?",z:"是實火還是陰虛？",
   o:[{a:"胃火熾盛 Blazing Stomach Fire",ok:1,n:"Correct — <b>eats a lot</b> and is hungry again. Stomach Yin deficiency is hungry but <b>cannot</b> eat. 胃火消穀善飢；胃陰虛則飢而不欲食。"},
      {a:"胃陰虛 Stomach Yin deficiency",ok:0,n:"That has a cracked peeled tongue, dry throat in the afternoon and a thready pulse. 胃陰虛舌裂少苔、午後咽乾、脈細。"},
      {a:"食滯胃脘 Food stagnation",ok:0,n:"That comes with sour belching and aversion to food after overeating. 食滯噯腐惡食，多因暴飲暴食。"}]}],
 teach:"\"Hungry and eats\" is fire; \"hungry but cannot eat\" is Yin deficiency. One line separates the pair.",
 teachZ:"「善飢能食」為火，「飢不欲食」為陰虛。一句話分兩證。"},

{p:"痰熱壅肺 Phlegm-Heat obstructing the Lung",tier:5,pair:"痰濕阻肺",
 v:"A 62-year-old man, four days of worsening illness. Fever, cough with a barking sound; phlegm thick, yellow and hard to expectorate; chest pain on coughing; face flushed; thirst; scanty dark urine. Tongue: red with a yellow greasy coating. Pulse: slippery and rapid.",
 vz:"62歲男性，病重四日。發熱、咳聲重濁，痰黃稠難咯，咳則胸痛，面赤口渴，小便短赤。舌紅苔黃膩，脈滑數。",
 q:[{t:"Eight Principles.",z:"八綱辨證",
   o:[{a:"Interior · Heat · Excess 裡 · 熱 · 實",ok:1,n:"Fever, yellow sticky phlegm, greasy yellow coat, slippery rapid pulse — heat plus a substantial pathogen. 發熱、痰黃稠、苔黃膩、脈滑數，熱與有形之邪並見。"},
      {a:"Exterior · Heat 表 · 熱",ok:0,n:"Four days in with no floating pulse and no chills — the pathogen has moved inward. 病四日、脈不浮不惡寒，邪已入裡。"},
      {a:"Interior · Cold · Excess 裡 · 寒 · 實",ok:0,n:"Cold phlegm is white and thin with a white coat. 寒痰色白稀薄、苔白。"}]},
  {t:"Which organ?",z:"病在何臟？",
   o:[{a:"Lung 肺",ok:1,n:"Cough, phlegm, chest pain — the Lung's descending and dispersing functions are blocked. 咳、痰、胸痛，肺失宣降。"},
      {a:"Heart 心",ok:0,n:"No palpitations or shen disturbance. 無心悸神志之症。"},
      {a:"Stomach 胃",ok:0,n:"No epigastric or gum signs. 無脘痛齦腫。"}]},
  {t:"Phlegm-Damp or Phlegm-Heat?",z:"痰濕？痰熱？",
   o:[{a:"痰熱壅肺 Phlegm-Heat obstructing the Lung",ok:1,n:"Correct. Phlegm is present in both; <b>colour and temperature</b> decide: yellow sticky phlegm, fever, red tongue, yellow greasy coat, rapid pulse. 痰同而寒熱異：痰黃稠、發熱、舌紅苔黃膩、脈數。"},
      {a:"痰濕阻肺 Phlegm-Damp obstructing the Lung",ok:0,n:"That is chronic and cool: copious <b>white</b> phlegm, easy to bring up, white greasy coat, slippery but not rapid pulse. 痰濕阻肺病久偏寒：痰白量多易咯、苔白膩、脈滑不數。"},
      {a:"肺陰虛 Lung Yin deficiency",ok:0,n:"That is a dry cough with scanty phlegm and a peeled tongue. 肺陰虛乾咳少痰、舌少苔。"}]}],
 teach:"Once a greasy coating tells you phlegm is present, the only remaining question is its temperature — white and thin, or yellow and thick.",
 teachZ:"膩苔既定有痰，餘下只問寒熱——痰之白稀與黃稠。"},

{p:"肝血虛 Liver Blood Deficiency",tier:5,pair:"血瘀",
 v:"A 29-year-old designer. Dizziness and blurred vision; eyes dry and gritty by evening; numbness and cramping in the calves at night; nails brittle and ridged; periods scanty, pale and late. Complexion and lips pale without lustre. Tongue: pale. Pulse: thready.",
 vz:"29歲設計師。眩暈、視物昏花，入夜目乾澀，小腿夜間麻木抽筋，爪甲脆而不榮，月經量少色淡而後期。面唇淡白無華。舌淡，脈細。",
 q:[{t:"Eight Principles.",z:"八綱辨證",
   o:[{a:"Interior · Deficiency 裡 · 虛",ok:1,n:"Pale, thin, dry and lustreless with a thready pulse — a deficiency of substance. 面舌淡、脈細、失濡養，屬虛。"},
      {a:"Interior · Excess 裡 · 實",ok:0,n:"There is no pain that resists pressure, no forceful pulse. 無拒按之痛、脈不有力。"},
      {a:"Interior · Heat · Deficiency 裡 · 熱 · 虛",ok:0,n:"No night sweats or five-centre heat — blood is short, but Yin is not yet burning. 無盜汗五心煩熱，血虛未至陰虛內熱。"}]},
  {t:"Which organ, and what is lacking?",z:"病在何臟？所虛為何？",
   o:[{a:"Liver, and Blood 肝 · 血",ok:1,n:"The Liver stores blood, opens to the eyes, governs the sinews and shows in the nails — every sign here follows that chain. 肝藏血、開竅於目、主筋、其華在爪，諸症皆循此脈絡。"},
      {a:"Heart, and Blood 心 · 血",ok:0,n:"Heart blood deficiency leads with palpitations, insomnia and poor memory. 心血虛以心悸、失眠、健忘為主。"},
      {a:"Kidney, and Essence 腎 · 精",ok:0,n:"That shows in bones, teeth, hearing and development. 腎精不足見骨齒、耳聾、發育。"}]},
  {t:"Blood deficiency or blood stasis?",z:"血虛？血瘀？",
   o:[{a:"肝血虛 Liver Blood deficiency",ok:1,n:"Correct — <b>not enough</b> blood: pale, dry, numb, thready pulse. 血<b>不足</b>：色淡、乾澀、麻木、脈細。"},
      {a:"血瘀 Blood stasis",ok:0,n:"Stasis is blood that <b>cannot move</b>: fixed stabbing pain, purple tongue, choppy pulse, dark clots. 血瘀為血<b>不行</b>：刺痛固定、舌紫、脈澀、血塊色暗。"},
      {a:"肝陰虛 Liver Yin deficiency",ok:0,n:"Closely related, but Yin deficiency adds heat — red tongue with little coat, thready <b>rapid</b> pulse. 相近，然肝陰虛兼熱：舌紅少苔、脈細數。"}]}],
 teach:"Blood deficiency is emptiness; blood stasis is obstruction. Numbness and pallor belong to the first; fixed stabbing pain to the second.",
 teachZ:"血虛為不足，血瘀為不通。麻木色淡屬前者，刺痛固定屬後者。"},

{p:"肝鬱脾虛 Liver Qi Stagnation with Spleen Deficiency",tier:4,pair:"肝鬱氣滯",
 v:"A 34-year-old office worker. Rib-side and chest distension with frequent sighing; but also poor appetite, bloating after meals, and loose stools that come on when she is upset. Tired. Tongue: pale with a thin white coating, slightly toothmarked. Pulse: wiry on the left, weak on the right.",
 vz:"34歲上班族。胸脅脹滿、時時太息；兼納呆、食後腹脹，情緒不佳即便溏。倦怠。舌淡苔薄白、略有齒痕，脈左弦右弱。",
 q:[{t:"Eight Principles.",z:"八綱辨證",
   o:[{a:"Interior · Mixed excess and deficiency 裡 · 虛實夾雜",ok:1,n:"Wiry pulse and distension = excess (stagnation); toothmarks, fatigue and a weak right pulse = deficiency. 脈弦而脹屬實（氣滯）；齒痕、倦怠、右脈弱屬虛。"},
      {a:"Interior · Excess 裡 · 實",ok:0,n:"Pure stagnation would not bring fatigue, toothmarks or a weak pulse. 單純氣滯無倦怠、齒痕、脈弱。"},
      {a:"Interior · Deficiency 裡 · 虛",ok:0,n:"Pure deficiency would not bring a wiry pulse or emotional flare-ups. 單純虛證無脈弦、無隨情志發作。"}]},
  {t:"Which two organs, and in what relationship?",z:"何臟相干？關係為何？",
   o:[{a:"Liver overacting on the Spleen 肝木乘脾土",ok:1,n:"The Liver fails to course freely and invades the Spleen — stools loosen exactly when she is upset. 肝失疏泄而橫逆犯脾，故情志一動即便溏。"},
      {a:"Spleen failing to nourish the Liver 脾不養肝",ok:0,n:"That would lead with blood deficiency signs — pale lips, blurred vision, thready pulse. 當見血虛：唇淡、視昏、脈細。"},
      {a:"Liver and Kidney 肝與腎",ok:0,n:"No low-back, ear or heat signs. 無腰膝、耳竅、熱象。"}]},
  {t:"Name the pattern.",z:"證型為何？",
   o:[{a:"肝鬱脾虛 Liver Qi stagnation with Spleen deficiency",ok:1,n:"Correct — the most common combined pattern in modern practice. Treat both: course the Liver, strengthen the Spleen. 現代臨床最常見之合證。疏肝與健脾並施。"},
      {a:"肝鬱氣滯 Liver Qi stagnation alone",ok:0,n:"Alone it does not produce loose stools, toothmarks or fatigue. 單純肝鬱無便溏、齒痕、倦怠。"},
      {a:"脾氣虛 Spleen Qi deficiency alone",ok:0,n:"Alone it does not produce a wiry pulse or emotion-triggered flares. 單純脾虛無脈弦、無情志誘發。"}]}],
 teach:"Combined patterns are read as a relationship, not a list. Ask which organ moved first — here the Liver did, and the Spleen paid for it.",
 teachZ:"合證看的是關係，不是清單。先問誰先動——此案肝先動，脾受其累。"},

{p:"痰火擾心 Phlegm-Fire harassing the Heart",tier:4,pair:"心腎不交",
 v:"A 38-year-old man after weeks of heavy drinking and little sleep. Cannot sleep at all; agitated, talks rapidly, occasionally shouts; chest oppression; bitter taste; constipation. Tongue: red with a thick yellow greasy coating. Pulse: slippery, rapid and forceful.",
 vz:"38歲男性，數週飲酒多而睡眠少。徹夜不寐，煩躁多言，時而叫喊，胸悶口苦，大便秘結。舌紅苔黃厚膩，脈滑數有力。",
 q:[{t:"Eight Principles.",z:"八綱辨證",
   o:[{a:"Interior · Heat · Excess 裡 · 熱 · 實",ok:1,n:"Thick greasy yellow coat with a forceful slippery rapid pulse — substantial heat. 苔黃厚膩、脈滑數有力，屬有形實熱。"},
      {a:"Interior · Heat · Deficiency 裡 · 熱 · 虛",ok:0,n:"Deficiency heat is thready with a <b>peeled</b> tongue and night sweats. 虛熱脈細、舌少苔、盜汗。"},
      {a:"Interior · Cold · Excess 裡 · 寒 · 實",ok:0,n:"No cold signs. 無寒象。"}]},
  {t:"What is disturbing the shen?",z:"擾神者為何？",
   o:[{a:"Phlegm and fire together 痰與火",ok:1,n:"Greasy coat = phlegm; red tongue, rapid forceful pulse, agitation = fire. Together they harass the Heart shen. 膩苔主痰，舌紅脈數有力主火，痰火合而擾心神。"},
      {a:"Yin deficiency 陰虛",ok:0,n:"Yin deficiency insomnia is restless and thin — thready pulse, peeled tongue, night sweats. 陰虛失眠見脈細、舌少苔、盜汗。"},
      {a:"Blood deficiency 血虛",ok:0,n:"Blood deficiency insomnia is pale and quiet, with palpitations and a thready pulse. 血虛失眠面淡神怯、心悸、脈細。"}]},
  {t:"Name the pattern.",z:"證型為何？",
   o:[{a:"痰火擾心 Phlegm-Fire harassing the Heart",ok:1,n:"Correct — loud, agitated, thick-coated: an excess insomnia. 屬實證失眠：聲高、煩躁、苔厚。"},
      {a:"心腎不交 Heart and Kidney not communicating",ok:0,n:"That is a <b>deficiency</b> insomnia: night sweats, tinnitus, sore low back, thready rapid pulse. 屬虛證失眠：盜汗、耳鳴、腰痠、脈細數。"},
      {a:"心脾兩虛 Heart-Spleen deficiency",ok:0,n:"That insomnia is tired and pale with poor appetite. 心脾兩虛失眠倦怠面淡納差。"}]}],
 teach:"Insomnia splits first into excess and deficiency. Loud and thick-coated is excess; quiet and peeled is deficiency.",
 teachZ:"不寐先分虛實。聲高苔厚屬實，神怯苔少屬虛。"},

{p:"肺脾氣虛 Lung and Spleen Qi Deficiency",tier:4,pair:"脾氣虛",
 v:"A 26-year-old teacher catches every cold that passes through her class. Between colds: breathless on climbing stairs, sweats without exertion, soft voice; also poor appetite, bloating and loose stools. Tongue: pale, toothmarked, thin white coating. Pulse: weak, especially in the right middle position.",
 vz:"26歲教師，班上一有感冒必被傳染。平時動則氣促、自汗、聲低；兼納呆腹脹便溏。舌淡有齒痕、苔薄白，脈弱，右關尤甚。",
 q:[{t:"Eight Principles.",z:"八綱辨證",
   o:[{a:"Interior · Deficiency 裡 · 虛",ok:1,n:"Soft voice, spontaneous sweat, weak pulse, toothmarked tongue — qi deficiency. 聲低、自汗、脈弱、齒痕舌，屬氣虛。"},
      {a:"Exterior · Deficiency 表 · 虛",ok:0,n:"Frequent colds do involve a weak defensive layer, but the root here is interior qi. 屢感雖關衛表不固，然本在裡氣之虛。"},
      {a:"Interior · Excess 裡 · 實",ok:0,n:"No forceful pulse or thick coating. 脈不有力、苔不厚。"}]},
  {t:"Which two organs?",z:"何二臟？",
   o:[{a:"Lung and Spleen 肺與脾",ok:1,n:"Breathlessness, sweat and frequent colds = <b>Lung</b> qi and wei qi; appetite, bloating, loose stools = <b>Spleen</b>. 氣促、自汗、屢感屬肺氣與衛氣；納呆腹脹便溏屬脾。"},
      {a:"Lung and Kidney 肺與腎",ok:0,n:"That shows as chronic wheeze with low-back weakness — the Kidney failing to grasp qi. 肺腎見久喘、腰膝無力，腎不納氣。"},
      {a:"Heart and Spleen 心與脾",ok:0,n:"No palpitations or insomnia. 無心悸失眠。"}]},
  {t:"Name the pattern, and the chain.",z:"證型與因果為何？",
   o:[{a:"肺脾氣虛 Lung-Spleen Qi deficiency",ok:1,n:"Correct. \"Earth generates Metal\" — a weak Spleen fails to supply the Lung, so the defensive layer stays thin. 培土生金：脾虛不能養肺，衛表不固。"},
      {a:"表虛不固 Exterior deficiency alone",ok:0,n:"That names the symptom, not the root. Ask what left the exterior unguarded. 此為標，非本；當追問衛表何以不固。"},
      {a:"肺陰虛 Lung Yin deficiency",ok:0,n:"That is dry: dry cough, scanty phlegm, red peeled tongue, thready rapid pulse. 肺陰虛屬燥：乾咳少痰、舌紅少苔、脈細數。"}]}],
 teach:"When the exterior keeps failing, look inward for the supply line. Strengthening the Spleen is often how you strengthen the Lung.",
 teachZ:"衛表屢屢失守，當回頭看補給線。健脾往往即是補肺之法。"},

{p:"肝腎陰虛 Liver and Kidney Yin Deficiency",tier:4,pair:"腎陰虛",
 v:"A 52-year-old woman. Dizziness, ringing ears, dry gritty eyes and blurred vision; sore weak low back and knees; night sweats and heat in the palms and soles; irritable in the late afternoon; periods have become scanty. Tongue: red with little coating. Pulse: thready, rapid and wiry.",
 vz:"52歲女性。眩暈耳鳴，目乾澀、視物昏花；腰膝痠軟；盜汗、五心煩熱；午後煩躁；月經量少。舌紅少苔，脈細數而弦。",
 q:[{t:"Eight Principles.",z:"八綱辨證",
   o:[{a:"Interior · Heat · Deficiency 裡 · 熱 · 虛",ok:1,n:"Heat on a thready pulse with a peeled tongue = Yin deficiency heat. 熱象而脈細舌少苔，屬陰虛內熱。"},
      {a:"Interior · Heat · Excess 裡 · 熱 · 實",ok:0,n:"Excess heat is forceful with a thick yellow coat. 實熱脈有力、苔黃厚。"},
      {a:"Interior · Cold · Deficiency 裡 · 寒 · 虛",ok:0,n:"No cold signs. 無寒象。"}]},
  {t:"Which organs?",z:"病在何臟？",
   o:[{a:"Liver and Kidney 肝與腎",ok:1,n:"Dry eyes and blurred vision = <b>Liver</b>; tinnitus and sore low back = <b>Kidney</b>. They share one source. 目乾視昏屬肝，耳鳴腰痠屬腎；乙癸同源。"},
      {a:"Kidney alone 單純腎",ok:0,n:"The eyes and the wiry pulse bring the Liver in. 目症與脈弦提示肝亦在其中。"},
      {a:"Heart and Kidney 心與腎",ok:0,n:"That leads with insomnia and palpitations. 心腎不交以失眠心悸為主。"}]},
  {t:"Name the pattern.",z:"證型為何？",
   o:[{a:"肝腎陰虛 Liver-Kidney Yin deficiency",ok:1,n:"Correct — \"the Liver and Kidney share a source\" (乙癸同源); when one Yin is short, the other follows, especially around menopause. 乙癸同源，一陰虧則另一陰隨之，尤見於絕經前後。"},
      {a:"肝陽上亢 Liver Yang rising",ok:0,n:"Related — rising Yang often stands on this very deficiency — but its leading signs are a splitting headache and a forceful wiry pulse. 相關：陽亢多因此虛而起；然其主症為頭脹痛、脈弦有力。"},
      {a:"肝血虛 Liver Blood deficiency",ok:0,n:"Blood deficiency is pale without heat: pale tongue, thready pulse, no night sweats. 血虛面舌俱淡而無熱：脈細、無盜汗。"}]}],
 teach:"Liver and Kidney Yin fall together. Eyes and sinews report the Liver; ears, low back and bones report the Kidney.",
 teachZ:"肝腎之陰同盛同衰。目與筋報肝，耳、腰、骨報腎。"},

{p:"脾腎陽虛 Spleen and Kidney Yang Deficiency",tier:4,pair:"腎陽虛",
 v:"A 67-year-old man, ill for years. Diarrhoea just before dawn with undigested food; abdomen cold and dull-aching, better with a hot water bottle; cold hands and feet; sore cold low back; puffy ankles by evening; passes clear urine at night. Tongue: pale swollen, white slippery coating. Pulse: deep, slow and weak.",
 vz:"67歲男性，病延多年。黎明前泄瀉、完穀不化；腹部冷痛，得熱則減；手足不溫；腰冷痠痛；傍晚踝部浮腫；夜間小便清長。舌淡胖苔白滑，脈沉遲無力。",
 q:[{t:"Eight Principles.",z:"八綱辨證",
   o:[{a:"Interior · Cold · Deficiency 裡 · 寒 · 虛",ok:1,n:"Deep slow weak pulse, cold relieved by warmth, clear urine — deficiency cold. 脈沉遲無力、得溫則減、小便清長，屬虛寒。"},
      {a:"Interior · Cold · Excess 裡 · 寒 · 實",ok:0,n:"Excess cold is acute and resists pressure. 實寒起病急、拒按。"},
      {a:"Interior · Damp · Excess 裡 · 濕 · 實",ok:0,n:"Damp is present in the swelling, but it is the <b>result</b> of failing Yang, not the root. 水腫雖屬濕，然為陽衰之果，非其本。"}]},
  {t:"Which two organs?",z:"何二臟？",
   o:[{a:"Spleen and Kidney 脾與腎",ok:1,n:"Undigested food and cold abdomen = <b>Spleen</b> Yang; dawn diarrhoea, cold low back, nocturia and oedema = <b>Kidney</b> Yang. 完穀不化、腹冷屬脾陽；五更瀉、腰冷、夜尿、水腫屬腎陽。"},
      {a:"Spleen and Lung 脾與肺",ok:0,n:"No cough, sweating or repeated colds. 無咳、自汗、屢感。"},
      {a:"Kidney and Bladder 腎與膀胱",ok:0,n:"No urgency, burning or dark urine. 無尿急灼熱短赤。"}]},
  {t:"Name the pattern.",z:"證型為何？",
   o:[{a:"脾腎陽虛 Spleen-Kidney Yang deficiency",ok:1,n:"Correct — Kidney Yang is the pilot light under the Spleen's cooking pot; when it fails, food passes through undigested and water is not moved. 腎陽為脾土之火；火衰則完穀不化、水濕不行。"},
      {a:"脾陽虛 Spleen Yang deficiency alone",ok:0,n:"Alone it does not bring dawn diarrhoea, nocturia or a cold low back. 單純脾陽虛無五更瀉、夜尿、腰冷。"},
      {a:"腎陽虛 Kidney Yang deficiency alone",ok:0,n:"Alone it does not bring undigested food and abdominal bloating. 單純腎陽虛無完穀不化、腹脹。"}]}],
 teach:"Long illness travels downward and inward — chronic Spleen patterns often end at the Kidney, the root of all Yang.",
 teachZ:"久病由淺入深、由上及下——脾病日久，多終及於腎，腎為諸陽之本。"},

{p:"濕熱蘊脾 Damp-Heat in the Spleen",tier:5,pair:"寒濕困脾",
 v:"A 41-year-old sales manager, worse in humid summer weather. Fullness in the upper abdomen, nausea, no appetite; mouth bitter and sticky; thirsty but does not want to drink; body heavy with a low afternoon fever; stools sticky and hard to pass fully; urine dark. Tongue: red with a yellow greasy coating. Pulse: soft and rapid.",
 vz:"41歲業務，濕熱之季加重。脘腹痞悶、噁心納呆；口苦而黏，渴不欲飲；身重、午後低熱；大便黏滯不爽，小便黃。舌紅苔黃膩，脈濡數。",
 q:[{t:"Eight Principles.",z:"八綱辨證",
   o:[{a:"Interior · Heat · Excess 裡 · 熱 · 實",ok:1,n:"Yellow greasy coat and a rapid pulse — damp <b>and</b> heat, both substantial. 苔黃膩、脈數，濕熱並見，皆屬有形之實。"},
      {a:"Interior · Cold · Excess 裡 · 寒 · 實",ok:0,n:"Cold damp gives a <b>white</b> greasy coat, no thirst and no fever. 寒濕苔白膩、口不渴、無發熱。"},
      {a:"Interior · Heat · Deficiency 裡 · 熱 · 虛",ok:0,n:"A greasy coating rules out pure deficiency. 苔膩即非純虛。"}]},
  {t:"Which sign proves dampness rather than plain heat?",z:"何症可證有濕而非單純熱？",
   o:[{a:"Thirsty but unwilling to drink 渴不欲飲",ok:1,n:"Heat creates thirst; damp blocks the wish to drink. The pair together is the signature of damp-heat — with the greasy coat. 熱故渴，濕故不欲飲；配膩苔，為濕熱之典型。"},
      {a:"Dark urine 小便黃",ok:0,n:"That only tells you there is heat. 僅示有熱。"},
      {a:"Afternoon fever 午後低熱",ok:0,n:"Suggestive of damp-heat, but also seen in Yin deficiency. 提示濕熱，然陰虛亦可見午後熱。"}]},
  {t:"Name the pattern.",z:"證型為何？",
   o:[{a:"濕熱蘊脾 Damp-Heat in the Spleen",ok:1,n:"Correct — damp and heat glued together, which is why these cases are slow to clear. 濕熱膠著，故病程纏綿難速已。"},
      {a:"寒濕困脾 Cold-Damp encumbering the Spleen",ok:0,n:"That is the cold twin: white greasy coat, bland mouth, no thirst, no fever. 寒濕為其寒證對照：苔白膩、口淡不渴、無熱。"},
      {a:"肝膽濕熱 Damp-Heat in Liver and Gallbladder",ok:0,n:"That adds hypochondriac pain, yellowing of the eyes and a wiry pulse. 肝膽濕熱兼脅痛、目黃、脈弦。"}]}],
 teach:"Damp plus heat is the stickiest pairing in TCM. \"Thirsty but not drinking\" plus a greasy coat names it almost by itself.",
 teachZ:"濕熱最為膠著。「渴不欲飲」配膩苔，幾可獨立定證。"},

{p:"大腸濕熱 Damp-Heat in the Large Intestine",tier:5,pair:"膀胱濕熱",
 v:"A 24-year-old student, two days after a street-food meal. Abdominal pain with urgency; frequent stools that are foul, hot and sticky, with a burning sensation at the anus; fever; thirst. Tongue: red with a yellow greasy coating. Pulse: slippery and rapid.",
 vz:"24歲學生，食用路邊攤兩日後發病。腹痛裡急後重，便次頻多、臭穢黏滯、肛門灼熱；發熱、口渴。舌紅苔黃膩，脈滑數。",
 q:[{t:"Eight Principles.",z:"八綱辨證",
   o:[{a:"Interior · Heat · Excess 裡 · 熱 · 實",ok:1,n:"Acute, foul, burning, with a yellow greasy coat and a slippery rapid pulse. 起病急、臭穢灼熱、苔黃膩、脈滑數。"},
      {a:"Interior · Cold · Deficiency 裡 · 寒 · 虛",ok:0,n:"Deficiency cold diarrhoea is watery, odourless and painless-ish, with a deep slow pulse. 虛寒之瀉清稀無臭、痛不甚、脈沉遲。"},
      {a:"Exterior · Heat 表 · 熱",ok:0,n:"The pulse is not floating; the problem is in the bowel. 脈不浮，病在腸腑。"}]},
  {t:"Where is it?",z:"病位何在？",
   o:[{a:"Large Intestine 大腸",ok:1,n:"Urgency, burning at the anus, sticky foul stools — the bowel's conduction is disturbed by damp-heat. 裡急後重、肛灼、便黏臭，濕熱擾大腸傳導。"},
      {a:"Bladder 膀胱",ok:0,n:"That is the urinary twin: burning, frequent, urgent <b>urination</b>. 膀胱濕熱為其對照：尿頻急灼痛。"},
      {a:"Stomach 胃",ok:0,n:"Stomach patterns centre on the epigastrium, belching and vomiting. 胃病以脘部、噯氣、嘔吐為主。"}]},
  {t:"Name the pattern.",z:"證型為何？",
   o:[{a:"大腸濕熱 Damp-Heat in the Large Intestine",ok:1,n:"Correct. Same pathogen as bladder damp-heat, different gate — the sign that names the organ is which orifice burns. 邪同而竅異：何竅灼熱，即定何腑。"},
      {a:"膀胱濕熱 Damp-Heat in the Bladder",ok:0,n:"Same damp-heat, but that one burns on urination. 濕熱雖同，然彼灼在小便。"},
      {a:"食滯腸胃 Food stagnation",ok:0,n:"That gives foul belching and relief after passing stool, without burning or fever. 食滯噯腐、便後痛減，無灼熱發熱。"}]}],
 teach:"When two organs share one pathogen, the deciding question is not what it is but where it comes out.",
 teachZ:"兩腑同受一邪時，關鍵不在邪為何，而在其由何竅而出。"},

{p:"氣滯血瘀 Qi Stagnation with Blood Stasis",tier:5,pair:"血瘀",
 v:"A 43-year-old woman. Ten years of premenstrual breast and rib-side distension with irritability; over the last two years this has been joined by fixed stabbing pain in the lower abdomen, dark clotted periods, and a dull darkened complexion. Tongue: dark purple at the edges with stasis spots. Pulse: wiry and choppy.",
 vz:"43歲女性。經前乳房脅肋脹痛、煩躁已十年；近兩年更增少腹刺痛固定、經色暗有塊、面色晦暗。舌邊紫暗有瘀點，脈弦澀。",
 q:[{t:"Eight Principles.",z:"八綱辨證",
   o:[{a:"Interior · Excess 裡 · 實",ok:1,n:"Distension and stabbing pain that resist pressure, wiry and choppy pulse — obstruction, not emptiness. 脹痛刺痛拒按、脈弦澀，屬阻滯之實。"},
      {a:"Interior · Deficiency 裡 · 虛",ok:0,n:"Deficiency pain is dull and likes pressure. 虛痛隱隱喜按。"},
      {a:"Interior · Heat · Excess 裡 · 熱 · 實",ok:0,n:"No heat signs — no thirst, no yellow coat, no rapid pulse. 無熱象：不渴、苔不黃、脈不數。"}]},
  {t:"Read the timeline. What came first?",z:"看病程：何者先起？",
   o:[{a:"Qi stagnation first, then blood stasis 先氣滯，後血瘀",ok:1,n:"Ten years of distension (qi), then two years of stabbing pain (blood). \"Qi moves blood\" — when qi stops long enough, blood follows. 脹十年（氣），刺痛二年（血）。氣為血帥，氣滯日久必致血瘀。"},
      {a:"Blood stasis first, then qi stagnation 先血瘀，後氣滯",ok:0,n:"The history says otherwise — distension came a decade earlier. 病史相反：脹先於刺痛十年。"},
      {a:"They arose together 同時而起",ok:0,n:"The two-year gap in the history is the whole teaching point. 病史相差二年，正是此案要義。"}]},
  {t:"Name the pattern.",z:"證型為何？",
   o:[{a:"氣滯血瘀 Qi stagnation with blood stasis",ok:1,n:"Correct — treat both, but move the qi to move the blood. 二者並治，然行氣以行血。"},
      {a:"血瘀 Blood stasis alone",ok:0,n:"Alone it would not carry the distension and the emotional pattern. 單純血瘀無脹痛與情志相關。"},
      {a:"肝鬱氣滯 Liver Qi stagnation alone",ok:0,n:"Alone it would not carry the purple tongue, clots and choppy pulse. 單純氣滯無舌紫、血塊、脈澀。"}]}],
 teach:"Distension is qi; stabbing is blood. When a history shows distension first and stabbing later, you are watching qi stagnation mature into stasis.",
 teachZ:"脹屬氣，刺屬血。病史先脹後刺，即見氣滯久而成瘀。"},

{p:"心火亢盛 Blazing Heart Fire",tier:5,pair:"心腎不交",
 v:"A 31-year-old man under exam pressure. Restless and hot-tempered; painful ulcers on the tip of the tongue; insomnia with vivid dreams; face flushed; thirst for cold drinks; urine dark and scanty with a burning sensation. Tongue: red at the tip with a thin yellow coating. Pulse: rapid and forceful.",
 vz:"31歲男性，考試壓力大。心煩易怒；舌尖生瘡疼痛；失眠多夢；面赤、口渴喜冷飲；小便短赤灼熱。舌尖紅苔薄黃，脈數有力。",
 q:[{t:"Excess or deficiency heat?",z:"實熱？虛熱？",
   o:[{a:"Excess heat 實熱",ok:1,n:"A <b>forceful</b> rapid pulse with ulcers and a normal-thickness coating — excess fire, not deficiency heat. 脈數有力、口瘡、苔非少苔，屬實火。"},
      {a:"Deficiency heat 虛熱",ok:0,n:"Deficiency heat is thready with a peeled tongue, night sweats and afternoon flushes. 虛熱脈細、舌少苔、盜汗潮熱。"},
      {a:"Damp-heat 濕熱",ok:0,n:"There is no greasy coating and no heaviness. 無膩苔、無身重。"}]},
  {t:"Which organ, and how do you know?",z:"病在何臟？何以知之？",
   o:[{a:"Heart — the tongue tip is its mirror 心 · 舌尖候心",ok:1,n:"The Heart opens to the tongue; fire rises to the tip. Dark burning urine follows the Heart-Small Intestine pair. 心開竅於舌，火炎於尖；尿赤灼熱者，心移熱於小腸。"},
      {a:"Liver 肝",ok:0,n:"Liver fire shows at the eyes and rib-sides, with a wiry pulse and bitter taste. 肝火見目赤脅痛、脈弦口苦。"},
      {a:"Stomach 胃",ok:0,n:"Stomach fire shows at the gums with ravenous hunger. 胃火見齦腫、消穀善飢。"}]},
  {t:"Name the pattern.",z:"證型為何？",
   o:[{a:"心火亢盛 Blazing Heart Fire",ok:1,n:"Correct — and when it travels to the Small Intestine you get the burning urine. 心火亢盛，下移小腸則見尿赤灼熱。"},
      {a:"心腎不交 Heart-Kidney not communicating",ok:0,n:"That is the deficiency twin: night sweats, tinnitus, sore low back, thready rapid pulse. 其虛證對照：盜汗、耳鳴、腰痠、脈細數。"},
      {a:"痰火擾心 Phlegm-Fire harassing the Heart",ok:0,n:"That adds a thick greasy coat and chest oppression. 痰火兼苔厚膩、胸悶。"}]}],
 teach:"Three Heart patterns look similar at night. Ulcers and a forceful pulse mean fire; a greasy coat means phlegm-fire; night sweats and a thready pulse mean Yin deficiency.",
 teachZ:"心之三證夜間相似：口瘡脈有力為火，苔膩為痰火，盜汗脈細為陰虛。"},

{p:"營衛不和 Ying and Wei Disharmony",tier:5,pair:"陰虛盜汗",
 v:"A 48-year-old man sweats through the day without exertion; the sweating makes him feel chilly and he catches colds easily; he sleeps through the night dry. No fever, no thirst, no heat in the palms. Tongue: pale-red with a thin white coating. Pulse: moderate and slightly weak, floating on light touch.",
 vz:"48歲男性，白日不動而汗出，汗後畏風、易感冒；夜間睡中無汗。無發熱、不渴、無五心煩熱。舌淡紅苔薄白，脈緩略弱、輕取即得。",
 q:[{t:"When does he sweat — and what does that tell you?",z:"汗出於何時？何以辨之？",
   o:[{a:"By day, without exertion — spontaneous sweating 自汗",ok:1,n:"Daytime sweating without effort is <b>spontaneous sweat</b>, which belongs to qi and Yang. 白日動輒或不動而汗，為自汗，屬氣屬陽。"},
      {a:"At night, during sleep — night sweating 盜汗",ok:0,n:"Night sweating that stops on waking belongs to Yin deficiency — the opposite pattern. 睡中汗出、醒則汗止為盜汗，屬陰虛，恰為對照。"},
      {a:"Only with fever 發熱時汗出",ok:0,n:"He has no fever. 本案無發熱。"}]},
  {t:"Eight Principles.",z:"八綱辨證",
   o:[{a:"Exterior · Deficiency 表 · 虛",ok:1,n:"Sweating with aversion to wind and easy colds = the defensive layer is not holding. 汗出惡風、易感，為衛表不固。"},
      {a:"Interior · Heat · Deficiency 裡 · 熱 · 虛",ok:0,n:"That is the night-sweat pattern: red peeled tongue, thready rapid pulse, five-centre heat. 此為盜汗之證：舌紅少苔、脈細數、五心煩熱。"},
      {a:"Exterior · Excess 表 · 實",ok:0,n:"Exterior excess has <b>no</b> sweat and a tight pulse. 表實無汗、脈緊。"}]},
  {t:"Name the pattern.",z:"證型為何？",
   o:[{a:"營衛不和 Ying and Wei disharmony",ok:1,n:"Correct — the wei qi fails to secure the exterior and the ying leaks out as sweat. 衛不固表，營陰外泄而為汗。"},
      {a:"陰虛盜汗 Yin deficiency night sweating",ok:0,n:"That sweats <b>in sleep</b> and carries heat signs; this patient sleeps dry. 陰虛者睡中汗出且見熱象；本案夜寐無汗。"},
      {a:"濕熱蒸騰 Damp-Heat steaming outward",ok:0,n:"That brings sticky sweat, a greasy coat and a rapid pulse. 濕熱之汗黏膩、苔膩、脈數。"}]}],
 teach:"One question sorts most sweating cases: day or night? Day sweat is qi and Yang; night sweat is Yin.",
 teachZ:"辨汗一問足矣：晝抑或夜？晝汗屬氣屬陽，夜汗屬陰。"},

{p:"腸燥津虧 Dryness of the Intestines with Fluid Depletion",tier:5,pair:"大腸濕熱",
 v:"A 71-year-old woman, constipated for years. Stools dry and pellet-like, passed only every four or five days with great effort; no abdominal pain and no fever; dry mouth and skin; thin build. Tongue: red and dry with little coating. Pulse: thready and slightly rapid.",
 vz:"71歲女性，便秘多年。大便乾結如羊屎，四五日一行、努責難下；無腹痛發熱；口乾膚燥、形體消瘦。舌紅乾少苔，脈細略數。",
 q:[{t:"Eight Principles.",z:"八綱辨證",
   o:[{a:"Interior · Deficiency (with dryness) 裡 · 虛 · 燥",ok:1,n:"Years of illness, thin build, dry peeled tongue, thready pulse — fluids are depleted, not blocked. 病久形瘦、舌乾少苔、脈細，屬津虧而非阻結。"},
      {a:"Interior · Heat · Excess 裡 · 熱 · 實",ok:0,n:"Excess heat constipation comes with abdominal pain that resists pressure, fever, a thick yellow coat and a forceful pulse. 實熱便秘見腹痛拒按、發熱、苔黃厚、脈有力。"},
      {a:"Interior · Cold · Excess 裡 · 寒 · 實",ok:0,n:"Cold accumulation gives cramping pain relieved by warmth. 寒積見腹痛得溫則減。"}]},
  {t:"Why are the stools dry?",z:"何以致燥？",
   o:[{a:"Fluids and blood are insufficient to moisten the bowel 津血不足，腸失濡潤",ok:1,n:"The Large Intestine needs moisture to conduct. In the elderly, fluids and blood run short — the bowel dries. 大腸傳導賴津液濡潤；年高津血不足，腸道失潤。"},
      {a:"Heat has scorched the fluids 熱盛傷津",ok:0,n:"Possible in principle, but there is no fever, no thirst for cold drinks and no forceful pulse. 理論可能，然無發熱、無渴喜冷飲、脈不有力。"},
      {a:"Qi cannot move the stool 氣滯不行",ok:0,n:"Qi stagnation constipation comes with distension, belching and a wiry pulse. 氣滯便秘見腹脹噯氣、脈弦。"}]},
  {t:"Name the pattern.",z:"證型為何？",
   o:[{a:"腸燥津虧 Intestinal dryness with fluid depletion",ok:1,n:"Correct — moisten, do not purge. Strong purgatives here would deplete the fluids further. 當潤而不當攻；峻下更傷其津。"},
      {a:"大腸濕熱 Damp-Heat in the Large Intestine",ok:0,n:"That is acute, foul, urgent and burning — the opposite picture. 濕熱者起病急、臭穢裡急灼熱，恰為相反。"},
      {a:"脾虛便秘 Spleen deficiency constipation",ok:0,n:"That version has an urge but no strength to push, with fatigue and a pale tongue. 脾虛便秘者有便意而努爭乏力，兼倦怠舌淡。"}]}],
 teach:"Not every constipation is heat. Dry and quiet means moisten; painful and forceful means drain. Reading this wrong harms the patient.",
 teachZ:"便秘未必屬熱。乾而靜者宜潤，痛而實者宜下；辨之有誤則傷人。"},

/* ══════════════════════════════════════════════════════════════
   Combined organ patterns — added with chapters 11–20

   Ten of these have a chapter of their own, so meeting one here is a
   second sighting of a case the player has already reasoned through.
   Four (Liver invading the Stomach, Lung and Kidney yin deficiency,
   Heart and Lung qi deficiency, Liver blood with Kidney essence
   depletion) appear only here — the daily roster is where they live.
   ══════════════════════════════════════════════════════════════ */

{p:"肝脾不和 Liver invading the Spleen",tier:4,
 v:"A 34-year-old accounts clerk. Distending pain under both ribs that moves about, worse in busy weeks. Bloating, poor appetite, loose stool with a feeling of not having finished, and belly pain that eases after passing stool. He sighs a great deal. Tongue: pale with a thin white coat. Pulse: wiry.",
 vz:"34歲帳房。兩脅脹痛而走竄，事忙則甚。腹脹納差，便溏而有里急後重感，腹痛得便則減。善太息。舌淡苔薄白，脈弦。",
 q:[{t:"What kind of pain is this, and what does it name?",z:"其痛何屬？所主為何？",
   o:[{a:"Distending and wandering — qi stagnation 脹而走竄，氣滯",ok:1,n:"Distending, moving pain that varies with mood and eases with a sigh is qi. Stabbing fixed pain would be blood; dull pain welcoming pressure would be deficiency. 脹痛走竄、隨情志而變、得太息則減者，氣也。刺痛固定者血；隱痛喜按者虛。"},
      {a:"Stabbing and fixed — blood stasis 刺痛固定，血瘀",ok:0,n:"His pain moves and answers to a sigh. Stasis pain does neither. 本案痛能走竄，且得太息而減；瘀痛則不然。"},
      {a:"Burning — fire 灼痛，火",ok:0,n:"No heat signs at all: pale tongue, thin white coat, no thirst, no bitter mouth. 通身無熱：舌淡苔薄白、不渴、口不苦。"}]},
  {t:"Two organs. Which way did it travel?",z:"二臟同病。其傳何向？",
   o:[{a:"Liver overacting on the Spleen 肝乘脾（木剋土）",ok:1,n:"Wood normally restrains Earth; when Liver qi is constrained it presses too hard on the Spleen. This is <b>overacting 相乘</b> — along the controlling cycle, not against it. 木本剋土，肝鬱則乘之太過。此為相乘，順其所勝之序而過之。"},
      {a:"Spleen insulting the Liver 脾侮肝",ok:0,n:"Earth does not restrain Wood, so there is no relationship here to reverse. And the emotional trigger names the Liver as the origin. 土不剋木，無序可反。且其因於情志，正指肝為其始。"},
      {a:"Liver fire insulting the Lung 肝火侮肺",ok:0,n:"That is the direction word for Liver into Lung, and there is no cough or chest sign here. 肝犯肺乃用「侮」字，且本案無咳無胸症。"}]},
  {t:"Which formula does the examination lock to this pattern?",z:"考試以何方鎖此證？",
   o:[{a:"逍遙散 Xiao Yao San",ok:1,n:"Liver invading the Spleen is the IBS picture, and Xiao Yao San is its formula. Its neighbour is Liver invading the Stomach — belching and acid rather than loose stool — which takes Chai Hu Shu Gan San 柴胡疏肝散. 肝脾不和即腸易激之屬，方用逍遙散。其鄰證為肝胃不和：噯氣吞酸而非便溏，方用柴胡疏肝散。"},
      {a:"歸脾湯 Gui Pi Tang",ok:0,n:"That is Heart blood with Spleen qi deficiency — worry, palpitations, bleeding. 此心血虛脾氣虛之方：憂思、心悸、出血。"},
      {a:"六君子湯 Liu Jun Zi Tang",ok:0,n:"That is Lung and Spleen qi deficiency — cough with phlegm plus poor digestion. 此肺脾氣虛之方：咳痰兼納差。"}]}],
 teach:"Emotional trigger, wandering rib pain, sighing and a wiry pulse point at the Liver. Bloating, poor appetite and loose stool point at the Spleen. Together, with the Liver as the cause, that is overacting — and the direction word is what the examination is really asking for.",
 teachZ:"因情志而發、脅痛走竄、善太息、脈弦，指肝；腹脹、納差、便溏，指脾。二者合而以肝為因，即相乘。考題所真問者，其向也。"},

{p:"肺脾氣虛 Lung and Spleen Qi Deficiency",tier:4,
 v:"A 58-year-old weaver, coughing every winter for six years. Copious white phlegm, easily brought up. Poor appetite, bloating after eating, loose stool. Voice low, disinclined to speak, short of breath on stairs. Tongue: pale with a white slippery coat. Pulse: thready and weak.",
 vz:"58歲織工，六年來每冬即咳。痰多色白易咯。納差，食後腹脹，便溏。聲低懶言，登階氣短。舌淡苔白滑，脈細弱。",
 q:[{t:"Where does the phlegm come from?",z:"其痰何由而生？",
   o:[{a:"The Spleen makes it; the Lung stores it 脾為生痰之源，肺為貯痰之器",ok:1,n:"The classical line, and it is the whole case. A Spleen too weak to transform fluid leaves damp, damp congeals into phlegm, and the phlegm collects in the Lung. Treating the Lung alone empties the jar without stopping the source. 古語盡之。脾虛不運則濕停，濕聚成痰，痰貯於肺。但治其肺，是去其器中之物而不絕其源。"},
      {a:"The Lung manufactures phlegm when it is cold 肺遇寒則自生痰",ok:0,n:"The Lung stores phlegm; it does not make it. Locating production in the Spleen is what makes the treatment work. 肺貯痰而不生痰。知其生於脾，其治乃效。"},
      {a:"The Kidney fails to hold fluid 腎不主水",ok:0,n:"Kidney involvement would bring oedema, a cold sore back and nocturnal urination. None is present. 腎病當見水腫、腰冷、夜尿，本案皆無。"}]},
  {t:"What is the five-phase relationship, and the treatment principle?",z:"其五行關係為何？治法何名？",
   o:[{a:"Mother and child — bank up earth to generate metal 母子·培土生金",ok:1,n:"Earth generates Metal, so the Spleen is the mother of the Lung. Build the mother and the child is fed — which is why the formula is Liu Jun Zi Tang 六君子湯, a Spleen formula, for a patient whose loudest complaint is a cough. 土生金，脾為肺之母。補母則子得養，故雖以咳為主訴，而方取六君子湯，脾劑也。"},
      {a:"Controlling — the Spleen restrains the Lung 相剋·脾剋肺",ok:0,n:"There is no controlling relationship between Earth and Metal. 土金之間本無相剋。"},
      {a:"Insulting — the Lung insulting the Spleen 相侮·肺侮脾",ok:0,n:"Insulting reverses a controlling relationship, and there is none here to reverse. 侮者反其所勝之序；此本無序可反。"}]},
  {t:"Is there heat anywhere in this case?",z:"本案有熱否？",
   o:[{a:"No — and that is what makes warming and drying the right direction 無熱，故溫燥為宜",ok:1,n:"White slippery coat, pale tongue, phlegm that is white and easy to bring up, a thready weak pulse. Compare phlegm-heat: yellow sticky phlegm hard to expectorate, a greasy yellow coat, a slippery rapid pulse. The colour of the phlegm alone would nearly settle it. 苔白滑、舌淡、痰白易咯、脈細弱。較之痰熱：痰黃稠難咯、苔黃膩、脈滑數。但憑痰色，幾已可決。"},
      {a:"Yes — six years of illness always generates heat 病久必化熱",ok:0,n:"Chronic illness often depletes rather than heats. Read the signs, not the calendar. 久病多致虛，未必化熱。當據其證，不據其年。"},
      {a:"Yes — the bloating after eating is食滯化熱",ok:0,n:"Food stagnation with heat is sour belching, a foul mouth and a thick yellow coat. His bloating is the emptiness of a Spleen that cannot move. 食滯化熱者噯腐、口穢、苔黃厚。本案之脹，脾虛不運之虛脹也。"}]}],
 teach:"Cough plus digestion is the pair to notice. Once you have both, ask which is the mother — the Spleen — and treat there. The phlegm is white and easy, so nothing is hot, and the treatment warms and dries.",
 teachZ:"咳與納，二者並見即當留意。既得其二，則問孰為母——脾也——而治之。痰白而易，是無熱，故其治溫而燥。"},

{p:"肝腎陰虛 Liver and Kidney Yin Deficiency",tier:4,
 v:"A 52-year-old dyer. Dizziness, headache, ringing in both ears, vision blurring by evening. Dry mouth and throat, sore low back and weak knees, heat in the palms and soles after noon, night sweats, red cheeks. Tongue: red with almost no coating. Pulse: thready and rapid.",
 vz:"52歲染工。頭暈頭痛，兩耳鳴，入暮視物模糊。口咽乾燥，腰痠膝軟，午後五心煩熱，盜汗，顴紅。舌紅少苔，脈細數。",
 q:[{t:"Blurred vision together with tinnitus points where?",z:"視糊兼耳鳴，指向何處？",
   o:[{a:"Liver and Kidney — the Liver opens into the eyes, the Kidney governs the ears 肝腎",ok:1,n:"Two organs, two orifices, one sentence — and a standard board key. Behind it is <i>Liver and Kidney share a source</i> 乙癸同源: Kidney essence produces Liver blood, so the two fall short together. 二臟二竅，一語可決，為考試常鍵。其理在乙癸同源：腎精化肝血，故二者同虧。"},
      {a:"Heart and Liver 心肝",ok:0,n:"Heart and Liver blood deficiency blurs vision too, but brings palpitations and forgetting rather than tinnitus — and it has no heat. 心肝血虛亦能視糊，然兼心悸健忘而不見耳鳴，且無熱。"},
      {a:"Spleen and Stomach 脾胃",ok:0,n:"Their orifice is the mouth, and their signs are appetite and stool. 脾胃開竅於口，其候在納在便。"}]},
  {t:"Yin or yang deficiency — and what decides it?",z:"陰虛乎？陽虛乎？何以決之？",
   o:[{a:"Yin — because the emptiness came with heat 陰虛，虛而有熱",ok:1,n:"One question settles it: hot or cold? Yang deficiency is cold — chilled limbs, clear copious urine, a pale wet tongue, a slow pulse. Yin deficiency is hot — afternoon heat, night sweats, burning palms, a red tongue with no coat, a rapid pulse. He has the second list entire. 一問可決：熱乎寒乎？陽虛者寒：肢冷、尿清長、舌淡潤、脈遲。陰虛者熱：午後潮熱、盜汗、手足心熱、舌紅無苔、脈數。本案全屬後者。"},
      {a:"Yang — the sore low back and weak knees say Kidney yang 陽虛",ok:0,n:"A sore low back belongs to the Kidney in general, not to yang in particular. The temperature decides which half. 腰痠膝軟乃腎之通候，不專屬陽。決其陰陽者，寒熱也。"},
      {a:"Qi — the tiredness 氣虛",ok:0,n:"Qi deficiency is a weak voice, breathlessness, daytime sweating and no heat. 氣虛者聲低、短氣、自汗，且無熱。"}]},
  {t:"Which formula, and which single finding would change the answer?",z:"當用何方？何一證足以易其答？",
   o:[{a:"六味地黃丸 Liu Wei Di Huang Wan — a pale wet tongue would change it 舌淡潤則易其答",ok:1,n:"Six-Flavour Rehmannia is the lock for Liver and Kidney yin deficiency. A pale, wet, swollen tongue with a slow pulse would move the case to Kidney yang deficiency and reverse the entire treatment — which is why the tongue is looked at before the formula is chosen. 六味地黃丸為肝腎陰虛之鎖。若見舌淡胖潤而脈遲，則轉屬腎陽虛，其治全反。故必先觀舌而後定方。"},
      {a:"百合固金湯 Bai He Gu Jin Tang",ok:0,n:"That is Lung and Kidney yin deficiency — cough with blood-streaked sputum, hoarseness. No cough here. 此肺腎陰虛之方：咳而痰中帶血、聲嘶。本案無咳。"},
      {a:"龜鹿二仙膠 Gui Lu Er Xian Jiao",ok:0,n:"That is Liver blood with Kidney essence depletion — premature ageing and reproductive decline <i>without</i> marked heat or cold. He has marked heat. 此肝血腎精虧虛之方：早衰、生殖衰退，而<b>無</b>明顯寒熱。本案熱象甚明。"}]}],
 teach:"Blurred vision with tinnitus is a two-word key. Then decide yin or yang by temperature alone, and the formula follows. The same two organs with no heat and no cold is a different pattern entirely.",
 teachZ:"視糊兼耳鳴，二字之鍵。次以寒熱定其陰陽，方即隨之。同此二臟而寒熱俱無者，又別為一證。"},

{p:"脾腎陽虛 Spleen and Kidney Yang Deficiency",tier:4,
 v:"A 61-year-old ferryman. Woken every day before first light by urgent diarrhoea containing undigested food, with no foul smell. Belly pain relieved by warmth and by a hand pressed on it. Legs pit when pressed. Low back and knees cold and aching. Passes clear copious urine three or four times a night. Tongue: pale, swollen, tooth-marked, white slippery coat. Pulse: deep, slow and weak.",
 vz:"61歲船家。每日天未亮即為急瀉所醒，便中有完穀，無臭穢。腹痛喜溫喜按。下肢按之成凹。腰膝冷痛。夜溺清長三四次。舌淡胖有齒痕、苔白滑，脈沉遲無力。",
 q:[{t:"The diarrhoea keeps an appointment. What does the hour tell you?",z:"其瀉守時。時辰所告者何？",
   o:[{a:"Daybreak is when yang should rise, and his does not 黎明陽當生而不生",ok:1,n:"The fifth watch is the hinge of the day: yin spent, yang not yet risen. A patient whose gate-of-life fire is low cannot hold the bowel through the coldest, most yin hour there is. <i>Daybreak diarrhoea</i> — cock-crow diarrhoea in the English wording — is a one-symptom lock. 五更者，一日之樞：陰盡而陽未升。命門火衰者，當此至陰之時不能自固。「五更泄瀉」，英作 daybreak / cock-crow diarrhea，一症鎖之。"},
      {a:"Nothing — only the stool matters 時辰無關",ok:0,n:"Loose stool has a dozen causes; loose stool at daybreak every day has essentially one. When a symptom keeps time, the time is data. 便溏之因十數，日日黎明而瀉者其因幾一。症能守時，時即為據。"},
      {a:"It means damp-heat in the Intestines 腸中濕熱",ok:0,n:"Damp-heat diarrhoea is urgent, foul, burning, with a bitter mouth and dark urine. He has the opposite of all of them. 濕熱之瀉急迫穢臭灼肛，兼口苦尿赤。本案一一相反。"}]},
  {t:"One yang has failed, yet you see both undigested stool and standing water. Why?",z:"陽虛惟一，而完穀不化與水停並見，何也？",
   o:[{a:"One failure, two products — yang neither ripens food nor moves water 一虛而二果",ok:1,n:"Yang has two jobs here: it ripens and separates what is eaten, and it turns fluid into vapour so the body can move it. Lose it and food passes through recognisable while fluid sinks to the lowest place it can reach. Two symptoms, two functions, one deficiency. 陽於此有二職：腐熟水穀而分清濁，化氣行水而使之行。失之則完穀不化，而水停趨下。二症二職一虛。"},
      {a:"Two separate illnesses in one man 二病相值",ok:0,n:"Then you would write two prescriptions and fight yourself. Look for the one mechanism that explains everything before agreeing it is two. 若然，則二方相牴。必先求一機以貫諸證。"},
      {a:"The oedema is a Lung problem — wind water 風水",ok:0,n:"Wind water starts at the face, comes on in days, with a floating pulse and an exterior sign. His began at the ankles over a winter with a deep slow pulse. 風水先腫頭面，起於數日，脈浮兼表證。本案起於足踝，歷冬，脈沉遲。"}]},
  {t:"Which formula pairing?",z:"何方相合？",
   o:[{a:"四神丸＋理中丸 Si Shen Wan with Li Zhong Wan",ok:1,n:"Si Shen Wan warms the Kidney and secures the bowel; Li Zhong Wan warms the middle. The Kidney is the root here — the Spleen does not generate its own heat, it is warmed from below — so the pairing treats the fire and the pot together. 四神丸溫腎固腸，理中丸溫中。本案以腎為本：脾不自生其熱，賴下之火以溫。合之則火與釜俱治。"},
      {a:"六味地黃丸 Liu Wei Di Huang Wan",ok:0,n:"That enriches yin, for a hot, dry, red-tongued patient. This one is cold and wet throughout. 彼滋陰，為熱燥舌紅者設。本案通身寒濕。"},
      {a:"逍遙散 Xiao Yao San",ok:0,n:"For Liver invading the Spleen — emotional trigger, rib pain, alternating stool. There is no Liver sign here. 為肝脾不和而設：因情志、脅痛、便秘泄瀉交替。本案無肝證。"}]}],
 teach:"Reason from the clock, then from the chain, then from the water. The hour names the Kidney; the undigested food names the Spleen; the oedema is the same yang failure arriving at a different function.",
 teachZ:"先由時辰推之，次由傳變推之，末由水推之。時辰名其腎，完穀名其脾，水腫則同一陽虛而見於他職耳。"},

{p:"肝火犯肺 Liver Fire insulting the Lung",tier:4,
 v:"A 46-year-old troupe master. Cough for months, twice this week with streaks of blood. Burning pain fixed under the right ribs, worse after arguments. Bitter mouth, red eyes, distending headache, irritable, sleeps badly. Phlegm thick and yellow. Tongue: red with redder edges, yellow coat. Pulse: wiry and rapid.",
 vz:"46歲班主。咳數月，本旬兩見血絲。右脅下灼痛固定，爭執後尤甚。口苦目赤，頭脹痛，煩躁，寐差。痰黃稠。舌紅邊尤紅、苔黃，脈弦數。",
 q:[{t:"Full heat or empty heat?",z:"實火乎？虛火乎？",
   o:[{a:"Full — a thick yellow coat, a wiry forceful pulse, and no night sweats 實火",ok:1,n:"Four independent reasons. A thick coat means something substantial is present, not merely something missing. A wiry pulse has force. The irritability is loud rather than fretful. And there are no night sweats, no tidal heat, no red cheeks — the marks of empty heat are all absent. 其據有四：苔厚則有形之邪在；脈弦則有力；其煩為躁而非怯；且無盜汗、無潮熱、無顴紅——虛熱之候全無。"},
      {a:"Empty — the blood in the cough says yin is damaged 虛火",ok:0,n:"Blood in the cough happens in both, which is exactly why the two are examined together. Empty heat brings night sweats, a red peeled tongue and a thready pulse. He has a thick yellow coat and a wiry one. 咳血二證俱見，故考試必並辨之。虛熱者盜汗、舌紅無苔、脈細。本案苔黃厚而脈弦。"},
      {a:"Neither — this is blood stasis 血瘀",ok:0,n:"Stasis bleeding is dark and clotted, its pain is stabbing and fixed rather than burning, and it does not rise and fall with his temper. 瘀血之出色暗有塊，痛如刺而非灼，且不隨怒而進退。"}]},
  {t:"Which direction word does the examination want?",z:"考題所求之向字為何？",
   o:[{a:"Insulting 相侮 — Liver fire rising against the Lung",ok:1,n:"Metal normally restrains Wood. Liver fire strong enough turns and scorches the organ that should have restrained it — against the controlling cycle, which is <b>insulting</b>. Liver into Spleen or Stomach is <b>overacting</b>. Swapping the two words is the standard wrong answer. 金本剋木；肝火盛極，反灼所以制之者，逆其序，故曰侮。肝犯脾胃則曰乘。二字互易，即其常設之誤答。"},
      {a:"Overacting 相乘",ok:0,n:"That is the word for Liver into Spleen or Stomach, along the cycle. 此為肝犯脾胃之字，順其序者。"},
      {a:"Mother-child 母子",ok:0,n:"That is generation, not control — Spleen to Lung, for example. 此為相生而非相剋，如脾之於肺。"}]},
  {t:"Treat the Liver or the Lung?",z:"治肝乎？治肺乎？",
   o:[{a:"Cool the Liver first as the source, and quiet the Lung alongside 先清其肝，兼寧其肺",ok:1,n:"The Lung is where the symptom shows; the Liver is where the fire is made. Treat the Lung alone and this week's blood stops and returns after the next argument. Treat the Liver alone and the scorched Lung vessels heal slowly. Do both, Liver leading. 肺者見症之地，肝者生火之所。但治肺，則此旬血止而再爭復作；但治肝，則已灼之絡愈遲。當兼治而以肝為主。"},
      {a:"Cool the Lung only — that is where the blood is 惟清其肺",ok:0,n:"Treating where the symptom shows rather than where it comes from. It works briefly, for as long as he runs a theatre company. 治其所見而不治其所由。其效暫耳。"},
      {a:"Tonify the Lung so it can restrain the Liver again 補肺以復其制",ok:0,n:"Elegant and wrong in an excess pattern: you restore the relationship by removing the excess from Wood, not by feeding a Lung that is currently being burned. 於實證非宜：復其制者當減木之有餘，非增被灼之肺。"}]}],
 teach:"Hemoptysis plus rage is a one-symptom lock. Then check whether the heat is full or empty, because Lung and Kidney yin deficiency also coughs blood — and the two need opposite treatments.",
 teachZ:"咳血兼暴怒，一症鎖之。次審其熱之虛實：肺腎陰虛亦見咳血，而二者之治相反。"},

{p:"心肝血虛 Heart and Liver Blood Deficiency",tier:4,
 v:"A 29-year-old woman, one year after a difficult birth with heavy blood loss. Palpitations on standing, sleeps but dreams all night and wakes tired, forgets what she came into a room for. Eyes dry and vision blurring by evening, hands and forearms numb, calves cramp at night, nails brittle, periods scanty and pale. No night sweats; her feet are cold. Tongue: pale, small, slightly dry. Pulse: thready.",
 vz:"29歲婦人，產後一年，產時失血甚多。起則心悸，能寐而終夜多夢，醒仍疲，入室輒忘所為。目乾，入暮視糊，手臂麻木，夜間腓腸拘攣，爪甲乾脆，經少色淡。無盜汗，足冷。舌淡瘦稍乾，脈細。",
 q:[{t:"Of qi, blood, yin and yang — which is short?",z:"氣血陰陽，所虧者何？",
   o:[{a:"Blood 血虛",ok:1,n:"Take the four in turn. Not qi: her voice is normal, she is not breathless, she does not sweat by day. Not yang: no oedema, no clear copious urine, no slow pulse. Not yin: yin deficiency brings heat, and she has none. Blood: pale tongue, thready pulse, dry eyes, numbness, scanty pale periods — and a documented great loss of blood. 依次求之。非氣：聲不低、不短氣、日不自汗。非陽：無腫、無尿清長、脈不遲。非陰：陰虛必有熱，本案無之。血：舌淡、脈細、目乾、麻木、經少色淡，且確有大失血。"},
      {a:"Yin 陰虛",ok:0,n:"The commonest error here, because dry eyes and poor sleep sound like yin. But yin deficiency is shortage <i>plus heat</i>: night sweats, afternoon heat, burning palms, a red peeled tongue, a thready <i>rapid</i> pulse. Take the heat away and what is left is blood. 此處最易之誤，以目乾寐差似陰虛。然陰虛者不足<b>而有熱</b>：盜汗、潮熱、五心煩熱、舌紅無苔、脈細<b>數</b>。去其熱，所餘者血。"},
      {a:"Yang 陽虛",ok:0,n:"Her feet are cold, and that is the only thing pointing this way. Cold extremities in blood deficiency are blood not reaching the ends, not a failure of warmth at the centre. 惟足冷似之。血虛之四末不溫者，血不達耳，非中焦失溫。"}]},
  {t:"Two organs are named. What is the evidence for each?",z:"所名二臟，各憑何據？",
   o:[{a:"Heart from the mind, Liver from the body — spirit versus eyes, sinews, nails 心憑神志，肝憑形體",ok:1,n:"Heart blood deficiency shows in the mind, because the Heart houses the spirit: palpitations, dream-crowded sleep, forgetting. Liver blood deficiency shows in the body, because the Liver stores blood and sends it out: dry blurred eyes, numbness, cramp, brittle nails, scanty periods. She has both lists complete. 心血虛見於神志，心藏神故：悸、多夢、健忘。肝血虛見於形體，肝藏血而輸之故：目乾視糊、麻木、拘攣、爪脆、經少。二列俱全。"},
      {a:"Heart only — the eye symptoms follow from poor sleep 惟心而已",ok:0,n:"Dry eyes and numb hands are not downstream of bad sleep. They are Liver blood failing to reach the tissues it moistens. 目乾手麻非寐差之所生，乃肝血不能濡其所養。"},
      {a:"Liver only — the palpitations are anxiety 惟肝而已",ok:0,n:"Palpitations, dreaming and forgetting are three Heart findings, not a mood. 悸、夢、忘，心之三證，非情緒之謂。"}]},
  {t:"What is absent, and why does the absence matter?",z:"本案所無者何？其無也何以為重？",
   o:[{a:"No heat signs — which rules out yin deficiency 無熱之候，故非陰虛",ok:1,n:"Blood deficiency and yin deficiency share nearly every symptom she has: eyes, sleep, dizziness, a thin pulse. Heat is the only reliable line between them, and heat is exactly what is missing. When two patterns overlap this much, look for the discriminating absence before you look for another symptom. 血虛與陰虛，其症幾皆共有：目、寐、眩、脈細。所可恃以分者惟熱，而熱正其所無。二證相疊如此者，當先求其別於「所無」。"},
      {a:"No pain — which rules out stagnation 無痛，故非氣滯",ok:0,n:"True, and nobody was going to mistake this for Liver qi constraint. The pattern actually at risk of confusion is yin deficiency. 所言不誤，然本案本不易誤為肝鬱。所當防者陰虛也。"},
      {a:"Nothing important is absent 無足輕重",ok:0,n:"Then you would treat her for yin deficiency and load her with rich cloying tonics she cannot digest. 若然，則以陰虛治之，投滋膩之品而其脾不受。"}]}],
 teach:"Sort a blood-deficient patient's symptoms into two columns — mind for the Heart, eyes and sinews and nails for the Liver. Then check for heat: its absence is what separates blood deficiency from yin deficiency.",
 teachZ:"血虛之症宜分二欄：神志屬心，目筋爪屬肝。次察其熱：熱之有無，即血虛與陰虛之界。"},

{p:"肝胃不和 Liver invading the Stomach",tier:5,
 v:"A 41-year-old cook. Burning distending pain across the epigastrium and both ribs that moves about, much worse in the two hours after an argument with a supplier. Belching, sour regurgitation, nausea, occasional vomiting, hiccups. Depressed one day and short-tempered the next. Tongue: pale with a thin yellow coat. Pulse: wiry.",
 vz:"41歲廚人。胃脘連兩脅脹痛而灼，痛處游走；與人爭執後二時內尤甚。噯氣、吞酸、噁心，時或嘔吐、呃逆。或抑鬱，或易怒。舌淡苔薄黃，脈弦。",
 q:[{t:"Which organ is the Liver pressing on, and how do you know?",z:"肝所犯者何臟？何以知之？",
   o:[{a:"The Stomach — belching, acid and vomiting are Stomach qi rebelling upward 胃，噯氣吞酸嘔吐為胃氣上逆",ok:1,n:"Stomach qi should descend. When the Liver presses on it, it rebels upward and you get belching, acid regurgitation, nausea, vomiting and hiccups. Contrast Liver invading the Spleen: the Spleen should ascend, so when it fails the movement is downward — bloating and loose stool. Up versus down separates the two. 胃氣以降為順。肝犯之則上逆，故噯氣、吞酸、噁心、嘔吐、呃逆。較之肝犯脾：脾以升為順，失之則下陷，見腹脹便溏。升降之異，即二者之別。"},
      {a:"The Spleen — the pain is abdominal 脾，以其腹痛",ok:0,n:"Liver into Spleen gives bloating and loose stool, not acid and belching. Direction of rebellion is what tells them apart. 肝犯脾者腹脹便溏，非吞酸噯氣。所別在氣逆之向。"},
      {a:"The Gallbladder 膽",ok:0,n:"Gallbladder heat brings a bitter mouth, alternating chills and fever, and often right-sided rib pain — a different picture. 膽熱者口苦、寒熱往來，多見右脅痛，其象不同。"}]},
  {t:"Which formula does the examination lock to this?",z:"考試以何方鎖此證？",
   o:[{a:"柴胡疏肝散 Chai Hu Shu Gan San",ok:1,n:"Liver invading the Stomach is the GERD picture and Chai Hu Shu Gan San is its formula. Its neighbour, Liver invading the Spleen, is the IBS picture and takes Xiao Yao San 逍遙散. Learn the two as a pair, because the examination presents them as one. 肝胃不和即胃食道逆流之屬，方用柴胡疏肝散。其鄰證肝脾不和為腸易激之屬，方用逍遙散。宜成對而記，蓋考題並出之。"},
      {a:"逍遙散 Xiao Yao San",ok:0,n:"That is the Spleen version — loose stool, bloating, no acid. 此脾之屬：便溏、腹脹、不吞酸。"},
      {a:"六君子湯 Liu Jun Zi Tang",ok:0,n:"That is Lung and Spleen qi deficiency, a deficiency pattern. This one is constrained, not empty. 此肺脾氣虛之方，虛證也。本案為鬱而非虛。"}]},
  {t:"His tongue is pale but the coat is yellow. What does that mean?",z:"舌淡而苔黃，何謂也？",
   o:[{a:"Constraint has begun to turn to heat, but the underlying constitution is not hot 鬱漸化火，而其本不熱",ok:1,n:"Read the two separately: the tongue <b>body</b> reports the constitution and it is pale; the <b>coat</b> reports what is currently present and it has begun to yellow. Long-standing qi constraint generates heat — which is why the pain has become burning rather than merely distending. It is a signal to soothe the Liver before the fire is established, not a reason to reach for cold bitter herbs. 二者當分讀：舌<b>質</b>候其本，淡也；<b>苔</b>候其今，已漸黃。氣鬱日久則化火，故其痛由脹而轉灼。此當疏肝於火未成之先，非遽投苦寒之謂。"},
      {a:"The yellow coat is from food he has eaten 飲食染苔",ok:0,n:"Staining is real and worth ruling out by asking — but a yellow coat that arrives with burning pain and a wiry pulse is reporting the pattern. 染苔誠有，當問而排之。然苔黃而兼灼痛脈弦者，其所報在證。"},
      {a:"He is yin deficient 陰虛",ok:0,n:"Yin deficiency thins and peels the coat rather than yellowing it, and the tongue body goes red rather than pale. 陰虛則苔薄而剝，非黃；其質轉紅而不淡。"}]}],
 teach:"Liver into Stomach and Liver into Spleen are one examination question in two halves. Rebellion upward — belching, acid, vomiting — is the Stomach. Sinking downward — bloating, loose stool — is the Spleen. The formulas follow.",
 teachZ:"肝犯胃與肝犯脾，一題之兩半。氣逆而上者噯酸嘔吐，胃也；氣陷而下者腹脹便溏，脾也。方隨其證。"},

{p:"肺腎陰虛 Lung and Kidney Yin Deficiency",tier:5,
 v:"A 37-year-old scholar, thin, ill for over a year. Dry cough with scanty sticky sputum, sometimes blood-streaked. Voice hoarse, throat and mouth dry. Sore low back and weak knees, night sweats, afternoon tidal fever, flushed cheekbones, nocturnal emissions. Tongue: red with little coating. Pulse: thready and rapid.",
 vz:"37歲書生，形瘦，病逾一年。乾咳少痰而黏，時帶血絲。聲嘶，口咽乾燥。腰痠膝軟，盜汗，午後潮熱，顴紅，夢遺。舌紅少苔，脈細數。",
 q:[{t:"Two organs share this. What is the relationship between them?",z:"二臟同病。其相關何在？",
   o:[{a:"Metal and Water nourish each other — the Lung sends fluid down, the Kidney sends yin up 金水相生",ok:1,n:"The Lung descends fluid to the Kidney and the Kidney sends yin up to moisten the Lung, so a long shortage in one drains the other. This is why a chronic dry cough eventually shows a sore low back, and why treating the Lung alone in a case this old does not hold. 肺降津以下輸於腎，腎升陰以上潤於肺；一臟久虧，必及其二。故久之乾咳終見腰痠；而病久但治其肺，其效不固。"},
      {a:"Wood overacting on Metal 木乘金",ok:0,n:"That would be the Liver, and there is no anger, no bitter mouth, no wiry pulse, no rib pain. 此當責之肝，而本案無怒、無口苦、無弦脈、無脅痛。"},
      {a:"Earth generating Metal 土生金",ok:0,n:"That is the Spleen and Lung pair, and it presents with appetite and stool signs, not with night heat. 此脾肺之屬，其候在納在便，不在夜熱。"}]},
  {t:"There is blood in the sputum. How does this differ from Liver fire insulting the Lung?",z:"痰中帶血。與肝火犯肺何別？",
   o:[{a:"The heat here is empty — night sweats, tidal fever, a peeled tongue, a thready pulse 虛熱",ok:1,n:"Both cough blood, and the examination separates them on the nature of the heat. Empty heat: night sweats, afternoon tidal fever, flushed cheekbones, a red peeled tongue, a thready rapid pulse, a long slow illness. Full Liver fire: rage, bitter mouth, red eyes, thick yellow phlegm, a thick yellow coat, a wiry rapid pulse. 二證俱咳血，考試以熱之虛實別之。虛熱：盜汗、潮熱、顴紅、舌紅無苔、脈細數，病久而漸。肝火實：暴怒、口苦、目赤、痰黃稠、苔黃厚、脈弦數。"},
      {a:"There is no real difference 無所別",ok:0,n:"The treatments are opposite — one enriches yin, the other drains fire. Confusing them is not a small error. 其治相反：一則滋陰，一則瀉火。誤之非小。"},
      {a:"This one is caused by trauma 外傷所致",ok:0,n:"Nothing in the history says so, and traumatic bleeding would not come with tidal fever and night sweats. 其史無之，且外傷之血不兼潮熱盜汗。"}]},
  {t:"Which formula?",z:"當用何方？",
   o:[{a:"百合固金湯 Bai He Gu Jin Tang",ok:1,n:"The lock for Lung and Kidney yin deficiency — the chronic consumptive picture the old texts call 肺癆. It enriches yin and moistens the Lung rather than attacking heat, because there is no pathogen to attack, only a shortage. 肺腎陰虛之鎖，即古所謂肺癆之屬。其法滋陰潤肺而不攻熱，蓋無邪可攻，惟不足耳。"},
      {a:"六味地黃丸 Liu Wei Di Huang Wan",ok:0,n:"That is Liver and Kidney yin deficiency — blurred vision and tinnitus, no cough. 此肝腎陰虛之方：視糊耳鳴，而無咳。"},
      {a:"六君子湯 Liu Jun Zi Tang",ok:0,n:"Warming and drying, for cold damp phlegm. Given here it would dry a patient who is already parched. 溫燥之劑，為寒濕之痰而設。用於此，是燥其已枯者。"}]}],
 teach:"Chronic dry cough plus a sore low back plus night heat is the Lung-and-Kidney yin picture. The blood in the sputum makes it look like Liver fire — the deciding question is always whether the heat is full or empty.",
 teachZ:"久乾咳兼腰痠、夜熱，肺腎陰虛之象。痰中帶血似肝火，而所決者恆在熱之虛實。"},

{p:"心肺氣虛 Heart and Lung Qi Deficiency",tier:5,
 v:"A 66-year-old retired porter. Cough and wheeze for years, much worse on any exertion. Palpitations, a pressing fullness in the chest, dizziness, very tired, a faint voice, sweats without effort. Clear thin sputum. Face pale, lips faintly purple. Tongue: pale, swollen and tender, white slippery coat. Pulse: deep and weak, occasionally missing a beat.",
 vz:"66歲退役挑夫。咳喘有年，動則尤甚。心悸，胸中壓悶，頭暈，神疲，聲微，自汗。痰清稀。面色蒼白，唇微紫。舌淡胖嫩、苔白滑，脈沉弱，時見結代。",
 q:[{t:"What single substance is short, and how do you know?",z:"所虧者何物？何以知之？",
   o:[{a:"Qi — everything is worse on exertion, and nothing is hot or cold 氣虛，動則加重",ok:1,n:"Qi deficiency has a signature shape: the whole picture worsens with effort and eases with rest, because effort spends qi. Add a faint voice, spontaneous daytime sweating, tiredness, dizziness, a weak pulse — and no heat, no cold, no pain. 氣虛之形有其定象：動則諸症加重，得息則減，蓋動則耗氣。兼聲微、自汗、神疲、頭暈、脈弱，而無熱、無寒、無痛。"},
      {a:"Yang — the pale face and swollen tongue 陽虛",ok:0,n:"Yang deficiency would add cold: chilled limbs, clear copious urine, a slow pulse, cold pain relieved by warmth. He is not cold, only empty. Qi deficiency is the step before yang deficiency. 陽虛當兼寒：肢冷、尿清長、脈遲、冷痛得溫則減。本案不寒，惟虛耳。氣虛者，陽虛之先一步。"},
      {a:"Blood — the dizziness 血虛",ok:0,n:"Blood deficiency gives pale lips and nails, dry eyes, numbness and scanty periods, with a thready pulse. His problem is force, not filling. 血虛者唇甲淡、目乾、麻木、經少，脈細。本案所虧在力而不在充。"}]},
  {t:"Why are the lips faintly purple, and what does it warn you about?",z:"唇何以微紫？其所戒為何？",
   o:[{a:"Qi too weak to push blood — stasis is beginning 氣虛不能行血，瘀之萌",ok:1,n:"Qi is the commander of blood: blood does not move itself. When the commander weakens, blood slows, and slowed blood begins to congeal — dusky lips, a purplish tongue, and a pulse that occasionally fails to arrive. That is why the treatment principle is stated as <i>tonify Heart and Lung qi, and prevent stasis</i> — you treat the stasis before it is established. 氣為血帥，血不自行。帥弱則血緩，緩則漸凝：唇暗、舌紫、脈時一止。故其治法曰「補心肺氣，防血瘀」——治其瘀於未成之先。"},
      {a:"It is cold air 受寒所致",ok:0,n:"Cold lips would go with cold limbs and a slow pulse, and would improve indoors. His do not. 寒則唇青而兼肢冷脈遲，入室當減。本案不然。"},
      {a:"It is unimportant 無足輕重",ok:0,n:"It is the finding that tells you where this pattern is heading, and it changes the prescription. 此正告你此證之所趨者，且改其方。"}]},
  {t:"The pulse occasionally misses a beat. What do you do about that?",z:"脈時見結代。當如何？",
   o:[{a:"Document it and refer for medical assessment, and treat alongside that care 記錄之，轉介求醫，並行其治",ok:1,n:"An irregular beat in an elderly patient with breathlessness and chest fullness is a finding to hand on, not one to interpret alone. Pattern differentiation tells you how to treat; screening tells you whether this room is the right room. Both happen, and the referral is not optional. 老年而見氣促胸悶兼脈律不齊者，當轉而告之，非可獨斷。辨證定其治，篩查定其可否。二者並行，而轉介非可省。"},
      {a:"Nothing — a knotted pulse is a normal TCM finding 結脈為常見之診，可不論",ok:0,n:"It is a recognised pulse quality and it is also a physical finding about the heart. Recognising it in one framework does not excuse you from the other. 結代誠為脈之一象，然亦心之形證。識其一，不能免其二。"},
      {a:"Stop all treatment permanently 永久停治",ok:0,n:"Over-reaction in the other direction. Refer, then treat within your scope alongside medical care. 其反亦過。當轉介，而後於己之範圍內與醫者並治。"}]}],
 teach:"Worse on exertion, faint voice, spontaneous sweating and a weak pulse is qi deficiency. Cough and palpitations together name the Lung and the Heart. Dusky lips are the early sign of stasis, and an irregular beat is referred.",
 teachZ:"動則加重、聲微、自汗、脈弱，氣虛也。咳與悸並見，名其肺與心。唇暗者瘀之萌；脈律不齊者，當轉介。"},

{p:"心血瘀阻 Heart Blood Stasis",tier:5,
 v:"A 55-year-old salt-house steward. Six months of stabbing chest pain, always the same spot, worse after dark, spreading down the inside of the left arm to the little finger. Pressing makes it worse. Palpitations. Lips and nails dusky. He took a cart shaft to the chest eleven years ago. Less stamina than he had. Tongue: dark purple with stasis spots; the vessels beneath it are dark and full. Pulse: choppy, occasionally missing a beat.",
 vz:"55歲鹽行掌櫃。胸痛如刺半年，痛處固定，入夜尤甚，引及左臂內側至小指。拒按。心悸。唇甲青暗。十一年前為車轅撞胸。氣力不如昔。舌紫暗有瘀點，舌下絡脈青紫粗脹。脈澀，時見結代。",
 q:[{t:"Before anything else — what does this presentation require?",z:"餘事未論，此證所必先者為何？",
   o:[{a:"Screening and referral: exertional chest pain, radiation to the arm, an irregular beat 篩查並轉介",ok:1,n:"Chest pain that comes with exertion, spreads to the arm, comes with an irregular beat, or is worsening is referred the same day — every time, documented, and re-screened at every visit. Pattern differentiation tells you how to treat; screening tells you whether to treat here. This is the one presentation where taking the shortcut is dangerous. 胸痛因勞而發、放射至臂、脈律不齊，或日漸加重者，當日轉介，必記錄，且每診復篩。辨證定其治，篩查定其可否。惟此一證，省之則危。"},
      {a:"Choosing the right points, since the pattern is obvious 證既明，逕取其穴",ok:0,n:"The pattern being clear is not the same as the patient being safe to treat here. Two questions, answered separately, screening first. 證明與其人宜於此室受治，二事也。二問各答，而篩查在先。"},
      {a:"A full tongue and pulse record 詳錄舌脈",ok:0,n:"Good practice and not a substitute for acting on a red flag today. 誠善，然不能代今日之應對。"}]},
  {t:"The pain has a quality. What pathology does it name?",z:"其痛有性。所主為何？",
   o:[{a:"Stabbing, fixed, worse at night — blood stasis 刺痛固定夜甚，血瘀",ok:1,n:"Pain has a grammar: stabbing is blood, distending is qi, dull and better for pressure is deficiency, burning is fire, heavy is damp, cramping and better for warmth is cold. Fixed confirms substance; worse at night fits, because blood is yin and slows as yang withdraws. 痛有其法：刺痛主血，脹痛主氣，隱痛喜按主虛，灼痛主火，重痛主濕，絞痛得溫則減主寒。固定者有形，夜甚者血屬陰而陽入則行緩。"},
      {a:"Distending and wandering — qi stagnation 脹痛走竄，氣滯",ok:0,n:"His does not move and does not ease with a sigh. Qi stagnation left long enough becomes stasis, which may well be how this began. 本案不移，且不因太息而減。氣滯日久則成瘀，其始或正在此。"},
      {a:"Dull and relieved by pressure — deficiency 隱痛喜按，虛",ok:0,n:"He is depleted underneath, and the pain itself refuses pressure. Root and branch are different questions. 其本誠虛，而其痛拒按。標本異問。"}]},
  {t:"Root and branch?",z:"孰為本？孰為標？",
   o:[{a:"Root: qi too weak to move blood. Branch: the stasis that formed 本氣虛，標血瘀",ok:1,n:"Blood does not move itself. A man who now climbs stairs slowly and sweats doing it has lost the force that pushes it, and where blood slows it congeals. So: deficiency at the root, excess at the branch. Break the stasis and support the qi together — breaking alone empties him further and the stasis reforms. 血不自行。今登階而遲、動則汗，是推血之力已減；血緩則凝。故本虛而標實。當破瘀與益氣並行——但破不補，則虛甚而瘀復結。"},
      {a:"Pure excess — remove the blockage 純實",ok:0,n:"Then he feels better for a fortnight and worse by the next season. 若然，則旬日稍安，逾季更劇。"},
      {a:"Pure deficiency — supplement and the pain will go 純虛",ok:0,n:"Supplementing into a blocked vessel is the classic way to make stasis pain worse. 塞而補之，瘀痛所以益甚。"}]}],
 teach:"Screening comes before pattern differentiation in any chest pain. Then read the quality of the pain, then ask what let the stasis form — in a man of this age it is usually qi that has gone weak.",
 teachZ:"凡胸痛，篩查在辨證之先。次察痛之性質，末問瘀何由而成——此年之人，多因氣衰。"},

{p:"濕熱痹阻 Damp-Heat Obstructing the Channels",tier:5,
 v:"A 31-year-old dock porter, in the fourteenth day of monsoon rain. Right knee red, swollen, hot to the touch, refusing pressure, and much better for a cold cloth. The whole leg feels heavy. Afternoon fever without chills; sweating does not break it. Thirsty but does not want to drink much. Urine dark and scanty, stool sticky and never finished. Tongue: red with a greasy yellow coat. Pulse: slippery and rapid.",
 vz:"31歲碼頭挑夫，值梅雨第十四日。右膝紅腫，捫之灼手，拒按，得冷敷則舒。一腿重著。午後身熱不惡寒，汗出而熱不解。渴而不欲多飲。小便短黃，大便黏滯不爽。舌紅苔黃膩，脈滑數。",
 q:[{t:"Cold or hot? Decide before anything else.",z:"寒乎熱乎？此當先決。",
   o:[{a:"Hot — red, hot to the touch, better for cold 熱",ok:1,n:"Four independent findings agree: it burns under your hand, it is visibly red, cold relieves it and warmth makes it throb. This decision comes first because it decides the technique — get it wrong and you will moxa a joint that needs cooling. 四證同歸：捫之灼手、色赤、得涼則減、得溫則甚。此當先決者，以其定手法也；誤之則灸其當清者。"},
      {a:"Cold — it is a joint complaint in the wet season 寒",ok:0,n:"Season is context, not diagnosis. Damp weather produces cold-damp and damp-heat bi in equal measure; the difference is in the patient. 時令為境，非診斷。濕令之中，寒濕與濕熱並生，其別在人。"},
      {a:"Neither — the sinews are undernourished 筋失所養",ok:0,n:"Deficient sinews are weak, thin and slack, and the pain welcomes a hand. This joint refuses to be touched. 筋失養者痿弱而喜按。本節拒按。"}]},
  {t:"Bi has four kinds. Which is this?",z:"痹有四證。此屬何者？",
   o:[{a:"Heat bi with damp — fixed, swollen, worse in humidity 熱痹兼濕",ok:1,n:"Run the four. Moving bi is wind — pain that jumps between joints; his does not. Painful bi is cold — dramatically better with warmth; his is worse. Fixed bi is damp — heavy, swollen, worse in wet weather; that fits. Heat bi is red, hot and better for cold; that fits too. So: damp with heat in it. 試以四者次之。行痹屬風，痛走諸節，本案不然。痛痹屬寒，得溫大減，本案反甚。著痹屬濕，重腫而遇陰濕則甚，合。熱痹紅腫灼熱喜涼，亦合。故為濕中有熱。"},
      {a:"Painful bi — cold predominating 痛痹",ok:0,n:"Cold bi is the one that answers to warmth. He asks for cold water. 痛痹得溫則減。本案所求者江水。"},
      {a:"Moving bi — wind predominating 行痹",ok:0,n:"Wind moves and so does its pain. His has been in one knee for two years. 風性善行，其痛亦然。本案二年止在一膝。"}]},
  {t:"Damp and heat are both here. Which leads, and how can you tell?",z:"濕熱俱在。孰勝？何以知之？",
   o:[{a:"Damp — the coat is more greasy than yellow, the stool is sticky, the leg is heavy, thirst without drinking 濕重於熱",ok:1,n:"Damp leading: greasy more than yellow, heaviness, swelling, sticky unfinished stool, thirst without desire to drink, fever that does not break with sweat. Heat leading: yellow more than greasy, high fever, real thirst for cold drinks in quantity, a bounding pulse. He has almost the whole first list, so drain damp as the main line and clear heat alongside — the other way round would be cold and cloying, and cloying medicine makes damp worse. 濕重之候：苔膩多於黃、身重、腫、便黏、渴不欲飲、汗出熱不解。熱重之候：苔黃多於膩、壯熱、真渴喜冷飲而量多、脈洪。本案幾具前列之全，故以利濕為主而清熱佐之；反之則方偏寒膩，適助其濕。"},
      {a:"Heat — the joint is hot and the tongue is red 熱重於濕",ok:0,n:"Present is not predominant. No high fever, no real thirst, a coat more greasy than yellow, stool sticky rather than dry. 「有」非「勝」。無壯熱、無真渴、苔膩多於黃、便黏而不燥。"},
      {a:"It does not change the treatment 於治無涉",ok:0,n:"It changes it entirely — one calls for aromatic percolating herbs with a little cooling, the other for cold bitter herbs with a little damp-draining. 其涉甚大：一則芳化淡滲而少佐以清，一則苦寒而少佐以利濕。"}]}],
 teach:"Put your hand on the joint before you ask anything. Hot settles the thermal question and refusing pressure settles excess. Then name which of the four bi, then weigh damp against heat — that last judgement is what shapes the prescription.",
 teachZ:"未問之前先按其節。灼則寒熱已定，拒按則虛實已定。次定四痹之屬，末權濕熱孰勝——此一判，方之所由成也。"},

{p:"瘀血頭痛 Blood Stasis Headache",tier:5,
 v:"A 33-year-old wheelwright. Eight months of headache, always the same handspan above the right ear running forward to the temple. Boring, like a nail. Worse after dark and after a day bent over the lathe. Pressing does not help. A cart shaft struck that side of his head eight months ago and he was briefly unconscious; nothing has changed since. Face dull and darkish. Tongue: dark purple with stasis patches, coat thin. Pulse: fine and choppy.",
 vz:"33歲車匠。頭痛八月，恆在右耳上一掌之地，前及太陽。痛如錐鑽。入夜及久俯之後尤甚。按之不減。八月前為車轅擊其頭右側，當時短暫昏暈，此後其狀未變。面色晦暗。舌紫暗有瘀斑，苔薄。脈細澀。",
 q:[{t:"He pointed. Which channel owns that place?",z:"其指所指。此處屬何經？",
   o:[{a:"Shaoyang — the temple and the side of the head 少陽",ok:1,n:"The head is divided between channels, and the location alone eliminates most of the field. Taiyang: back of the head into the nape. Yangming: forehead and brow-ridge. Shaoyang: both sides, temple to ear. Jueyin: the vertex, drawing into the eye. Ask the patient to point before you ask anything else. 頭分諸經，但憑部位可去其大半。太陽：後頭連項。陽明：前額連眉稜。少陽：兩側顳部連耳。厥陰：巔頂牽引目系。凡問頭痛，先令其指。"},
      {a:"Taiyang — headaches are Taiyang 太陽",ok:0,n:"Taiyang owns the back of the head and the nape, not the whole skull. 太陽所主在後頭與項，非全顱。"},
      {a:"Jueyin — the Liver is behind most headaches 厥陰",ok:0,n:"Jueyin headache sits at the vertex and draws into the eye. His is above the ear. 厥陰頭痛在巔，牽引目系。本案在耳上。"}]},
  {t:"The channel is named. What kind of pain is it?",z:"經既定矣。其痛屬何？",
   o:[{a:"Blood stasis — boring, fixed, worse at night, after injury, purple tongue 血瘀",ok:1,n:"Five findings agree. Location names the channel, quality names the pathology — two separate questions, and you need both before you can choose a point. 五證同歸。部位定其經，性質定其理：二問也，二者俱得而後可定一穴。"},
      {a:"Liver yang rising 肝陽上亢",ok:0,n:"The commonest cause of one-sided headache, and the one you must exclude. Liver yang gives distending pain, dizziness, irritability, a red face and a wiry pulse, fluctuating with mood. He has none, and a clear injury instead. 偏頭痛之最常見者，必當排除。肝陽者脹痛、眩暈、易怒、面赤、脈弦，隨情志而變。本案皆無，而有明確外傷。"},
      {a:"Phlegm-damp clouding the head 痰濕",ok:0,n:"That headache is heavy, as though the head were wrapped, with a full chest, nausea and a thick greasy coat. His coat is thin and his pain is a nail. 痰濕之頭痛為重如裹，兼胸悶噁心、苔厚膩。本案苔薄，痛如釘。"}]},
  {t:"A headache this old after a head injury. What else do you owe him?",z:"外傷後之頭痛歷久如此，尚有何事當為？",
   o:[{a:"Establish that nothing has changed — no new symptoms, no steady worsening 確認其未變",ok:1,n:"A stable headache after a known injury is one thing. A headache that has changed character, is steadily worsening, newly wakes him, or arrives with new weakness, numbness, vomiting, fever, neck stiffness or visual change belongs with a physician the same day. His has been the same for eight months — but that is a judgement you make deliberately, and remake at every visit. 已知外傷之後其狀穩者，一事也。若性質已改、日漸加重、新見痛醒，或兼新起之肢弱、麻木、嘔吐、發熱、項強、視物異常者，當日即須就醫。本案八月如一——然此為審而後定之判斷，且每診必復為之。"},
      {a:"Nothing — the pattern is clear 證明，無他",ok:0,n:"The pattern being clear is not the same as the patient being safe to treat here. 證明與其人宜於此室受治，二事也。"},
      {a:"Tell him to stop working 令其停工",ok:0,n:"Kind, impractical, and not a safety measure. 意厚而勢不能，且非安全之計。"}]}],
 teach:"Headache is the complaint where location does the most work. Name the channel from where the finger goes, name the pathology from how the patient describes it, and screen a post-traumatic headache every visit.",
 teachZ:"頭痛之證，部位所決最多。由其指之所指定其經，由其言之所狀定其理；外傷後之頭痛，每診必篩。"},

{p:"肝血腎精虧虛 Liver Blood and Kidney Essence Depletion",tier:5,
 v:"A 44-year-old man and his wife, seen together, unable to conceive after three years. He: low libido, thinning semen, hair greying early and falling, teeth loosening, poor memory, ringing ears, vision blurring. No fever, no night sweats, no chilled limbs, no oedema. Tongue: pale. Pulse: thready and weak.",
 vz:"44歲男子偕其妻同診，三年不孕。其人性慾低，精液稀薄，髮早白而脫，齒動搖，記憶差，耳鳴，視物模糊。無發熱、無盜汗、無肢冷、無水腫。舌淡，脈細弱。",
 q:[{t:"What is conspicuously absent here, and why does it matter?",z:"本案顯然所無者何？何以為重？",
   o:[{a:"There is neither heat nor cold — which rules out both yin and yang deficiency 寒熱俱無，故非陰虛亦非陽虛",ok:1,n:"This is the pattern defined by an absence. Kidney yin deficiency would bring night sweats, tidal fever and a red peeled tongue. Kidney yang deficiency would bring cold limbs, oedema and clear copious urine. He has neither list — what remains is a shortage of substance itself: Liver blood and Kidney essence, with nothing hot or cold layered on top. 此證以「所無」而立。腎陰虛當見盜汗、潮熱、舌紅無苔；腎陽虛當見肢冷、水腫、尿清長。二列俱無，所餘者形質本身之虧：肝血與腎精，而無寒熱附之。"},
      {a:"There is no pain — so it is not stasis 無痛",ok:0,n:"True and not the deciding absence. Nobody would call this stasis; the patterns actually in contention are Kidney yin and Kidney yang deficiency. 誠然，而非所以決者。本案無人以為瘀；所當爭者，腎陰虛與腎陽虛耳。"},
      {a:"Nothing important is absent 無足輕重",ok:0,n:"Then you would warm him or enrich him and treat the wrong axis entirely. 若然，則或溫或滋，而所治之軸盡誤。"}]},
  {t:"Why do the hair, teeth, ears, eyes and memory all fail together?",z:"髮、齒、耳、目、記憶何以同衰？",
   o:[{a:"Essence produces marrow, marrow fills the brain and bone; the Kidney governs bone and hair, and Liver blood feeds the eyes 精生髓，髓充腦骨",ok:1,n:"One substance, many roofs. The Kidney stores essence; essence produces marrow; marrow fills the brain and the bones — so memory, teeth and bone go together. The Kidney also opens into the ears and its bloom is in the hair. Liver blood feeds the eyes and the sinews. Short of both, everything they nourish fails at once, which is what premature ageing <i>is</i>. 一物而所養者眾。腎藏精，精生髓，髓充腦與骨，故記憶、齒、骨同衰。腎又開竅於耳，其華在髮。肝血養目與筋。二者俱虧，則所養者一時俱敗——早衰之為病，正在於此。"},
      {a:"They are separate illnesses of middle age 中年諸病各不相干",ok:0,n:"Then you would treat five things and none of them. Pattern differentiation is the search for the one mechanism. 若然，則治五者而一無所治。辨證者，求其一機也。"},
      {a:"Damp obstructing the orifices 濕蒙清竅",ok:0,n:"Damp brings heaviness, a greasy coat and a slippery pulse, none of which is here. 濕者身重、苔膩、脈滑，本案皆無。"}]},
  {t:"Which formula does the examination lock to this?",z:"考試以何方鎖此證？",
   o:[{a:"龜鹿二仙膠 Gui Lu Er Xian Jiao",ok:1,n:"The lock for Liver blood with Kidney essence depletion — premature ageing and reproductive decline without marked heat or cold. It is a filling formula, built from substantial animal-derived medicinals, for a shortage of substance itself. 肝血腎精虧虛之鎖：早衰、生殖衰退而寒熱不著。其為填補之劑，取血肉有情之品，以補形質之虧。"},
      {a:"六味地黃丸 Liu Wei Di Huang Wan",ok:0,n:"That is Liver and Kidney <i>yin</i> deficiency, which comes with empty heat — night sweats, tidal fever, a red peeled tongue. He has none. 此肝腎<b>陰</b>虛之方，必兼虛熱：盜汗、潮熱、舌紅無苔。本案無之。"},
      {a:"歸脾湯 Gui Pi Tang",ok:0,n:"Heart blood with Spleen qi deficiency — worry, palpitations, bleeding. Different organs entirely. 心血虛脾氣虛之方：憂思、心悸、出血。所主之臟全異。"}]}],
 teach:"This is the combined pattern you identify by what is missing. No heat and no cold, with reproductive decline and premature ageing, is Liver blood with Kidney essence — and the formula is the one you will not have used anywhere else.",
 teachZ:"此證以「所無」而識之。寒熱俱無，而見生殖衰退與早衰者，肝血腎精虧虛也；其方亦他處所不用者。"}
,

{p:"肝膽濕熱 Damp-Heat in the Liver and Gallbladder",tier:4,pair:"寒濕困脾",
 v:"A 52-year-old wine-shop keeper, ten days ill. Distending pain under the right ribs, worse after fatty food; bitter taste on waking; nausea and two episodes of vomiting; skin and sclerae bright orange-yellow; dark, scanty urine; sticky stool that never feels finished; alternating spells of feeling hot then cool; itching skin at night. No high fever, no confusion, no bleeding, no weight loss. Tongue: red with a greasy yellow coating heaviest at the sides. Pulse: wiry and rapid.",
 vz:"52歲酒坊掌櫃，病十日。右脅下脹痛，食肥甘則甚；晨起口苦；噁心，曾嘔二次；身目黃而鮮明如橘；小便短赤；大便黏滯不爽；寒熱往來；夜間膚癢。無壯熱、無神昏、無出血、無消瘦。舌紅，苔黃膩而偏於舌邊，脈弦數。",
 q:[{t:"Before anything else — which kind of jaundice is this, and how do you know from across the room?",z:"未論其餘，此黃屬何？何以隔室而知之？",
   o:[{a:"Yang jaundice 陽黃 — bright orange-yellow, with heat signs",ok:1,n:"The colour decides the direction of the whole prescription and it is visible before the interview starts. <b>陽黃</b> is bright, the colour of a fresh tangerine, and comes with heat: fever, bitter mouth, dark scanty urine, red tongue with a greasy yellow coat, wiry rapid pulse — damp-heat, acute, cleared and drained. <b>陰黃</b> is dull and smoky like old paper, and comes with cold: cold limbs, no appetite, loose stools, a pale swollen tongue with a white greasy coat, a deep slow pulse — cold-damp, chronic, warmed and dried. 色定全方之向，且未問而可望。<b>陽黃</b>鮮明如橘，兼熱象：發熱、口苦、溲短赤、舌紅苔黃膩、脈弦數，濕熱也，其病急，治以清利。<b>陰黃</b>晦暗如煙燻，兼寒象：肢冷、納呆、便溏、舌淡胖苔白膩、脈沉遲，寒濕也，其病緩，治以溫化。"},
      {a:"Yin jaundice 陰黃",ok:0,n:"Yin jaundice is smoky and dull and comes with cold hands, no appetite and a slow pulse. His skin is bright, his pulse is fast and his urine is dark. 陰黃色晦暗，兼手冷、納呆、脈遲。今其膚鮮明、脈數、溲赤。"},
      {a:"The distinction does not change treatment 陰陽之分於治無涉",ok:0,n:"It reverses it. One takes cold bitter draining herbs, the other warm aromatic drying ones, and each harms the other pattern. 適相反耳。一治以苦寒清利，一治以溫燥芳化，互用則各傷其人。"}]},
  {t:"The bitter mouth and the alternating hot-and-cool spells belong to which classical picture?",z:"口苦與寒熱往來，屬何經之候？",
   o:[{a:"Shaoyang — the pathogen is caught between exterior and interior 少陽，邪在半表半裡",ok:1,n:"Three Shaoyang signs are named in the Shanghan Lun and he has two of them: <b>bitter mouth</b> 口苦, <b>dry throat</b> 咽乾, <b>dizzy vision</b> 目眩 — plus the cardinal sign, <b>alternating chills and fever</b> 寒熱往來, which says the pathogen is neither on the surface nor deep inside but struggling at the pivot. The Gallbladder channel is Shaoyang, and the rib-side is its territory. 《傷寒論》少陽三證：口苦、咽乾、目眩；今得其一，而更有<b>寒熱往來</b>之主證——邪不在表、不在裡，而爭於樞。膽為少陽，脅為其分野。"},
      {a:"Taiyang — an exterior pattern 太陽表證",ok:0,n:"An exterior pattern is new, floats, and brings aversion to wind with a floating pulse. His is ten days old with organ signs and a wiry pulse. 表證新起而脈浮、惡風。今其病十日，臟腑之證已具，脈弦。"},
      {a:"Yangming — interior heat 陽明裡熱",ok:0,n:"Yangming heat is high fever with copious sweating, great thirst and a surging pulse, and no chills at all. 陽明者大熱、大汗、大渴、脈洪大，且不惡寒。"}]},
  {t:"By which road do you take damp-heat out of this body?",z:"當由何路導其濕熱而出？",
   o:[{a:"Downward through the urine — open the water road 從小便而出，通利水道",ok:1,n:"治濕不利小便，非其治也 — to treat damp without opening the urine is not treatment. Damp is substantial and has to be carried somewhere; the lower water road is where it goes. This is why Yinchenhao Tang works as it does, and why the practical measure of progress is that the urine lightens before the skin does. Watch the urine, not the face. 「治濕不利小便，非其治也。」濕為有形，必有所歸，而其歸在下焦水道。茵陳蒿湯之效在此；驗效之實據，亦在溲色先淡而後膚黃始退。當察其溲，不當獨望其面。"},
      {a:"Outward by sweating 從汗而解",ok:0,n:"Sweating releases an exterior pathogen. This one is interior, and sweating wastes fluids while the damp stays. 汗法解表邪。此邪在裡，汗之徒傷其津而濕仍在。"},
      {a:"Warm and dry it, since damp is a yin pathogen 溫燥化之，以濕為陰邪",ok:0,n:"True of damp alone, wrong for damp with heat inside it — warming concentrates the heat and the patient worsens within days. When damp and heat travel together, the heat holds the veto. 論濕則然，論濕中有熱則否：溫之則助其火，數日而劇。凡濕熱並見，禁溫之權在熱。"}]}],
 teach:"Two lessons ride together here. First, jaundice divides into 陽黃 and 陰黃 before it divides any further, and the division is visible from the doorway — bright as a tangerine with heat, or smoky as old paper with cold. Second, damp needs an exit and the exit is the urine; cooling alone leaves the damp exactly where it was. And before either: a patient who has turned yellow gets screened for high fever, confusion, bleeding, painless progressive jaundice and weight loss before any pattern work at all.",
 teachZ:"此案二義並行。其一：黃疸先分陽黃、陰黃，而後乃及其餘；其分可望於門外——鮮明如橘而兼熱，或晦暗如煙而兼寒。其二：濕必有出路，其路在小便；徒清其熱者，濕仍如故。而先於二者：身黃之人，當先篩查壯熱、神昏、出血、無痛漸進性黃疸與消瘦，而後乃可辨證。"},

{p:"心腎陽虛 Heart and Kidney Yang Deficiency",tier:4,pair:"心腎不交",
 v:"A 61-year-old night watchman. Aversion to cold that a warm room does not fix; hands and feet cold to the wrist and ankle; palpitations on climbing stairs that settle when he stands still; weak aching low back and knees; copious clear urine, three or four times a night; both ankles swollen by evening, pitting, better by morning. Pale white face, never flushed. He can lie flat and his pulse does not pause. Tongue: pale and swollen with tooth marks, white coat, visibly wet. Pulse: deep, slow, thin.",
 vz:"61歲守夜人。畏寒而近火加衣不解，四肢厥冷至腕踝；登樓則心悸，靜立則平；腰膝痠軟；小便清長，夜起三四次；兩踝暮則浮腫、按之凹陷，晨則消。面色㿠白，無潮紅。能平臥，脈不歇止。舌淡胖有齒痕，苔白滑，脈沉遲細。",
 q:[{t:"Heart and Kidney are both involved. Which way has the circuit failed?",z:"心腎俱病。其交所壞者，何端？",
   o:[{a:"The fire cannot descend to warm the water — yang is short 火不下溫其水，陽虛也",ok:1,n:"In health the Heart fire descends to warm the Kidney water and the Kidney water rises to cool the Heart fire — 水火既濟. Two ways to break it, and they look nothing alike. Here the yang itself is short, so there is not enough fire to send down: the water is unwarmed, is not moved, and pools at the lowest point. The other failure, the 心腎不交 of the insomnia chapters, is a shortage of <b>water</b>: the unrestrained fire floats up and the patient is restless, sleepless, sweating at night, red-tongued and fast-pulsed. Same axis, opposite end, opposite treatment — and one look at the tongue separates them. 平人則心火下溫腎水，腎水上濟心火，水火既濟。其壞有二端而形貌迥異。今陽自虛，無火可下：水失其溫而不行，聚於身之最下。其另一端即不寐諸章所言之心腎不交——<b>水</b>虧而火浮於上，其人煩、不寐、盜汗、舌紅、脈數。同軸異端，其治相反，而一望其舌即判。"},
      {a:"The water cannot rise to cool the fire — yin is short 水不上濟其火，陰虛也",ok:0,n:"Check it against him: not restless, not sleepless, no night sweats; tongue pale swollen and wet; pulse slow. Every finding is the opposite. 以其人核之：不煩、不失眠、無盜汗；舌淡胖而滑，脈遲。無一不反。"},
      {a:"Heart fire is excessive and burning the water away 心火亢盛，灼其水",ok:0,n:"That patient is hot, red-faced, thirsty, with mouth ulcers and a forceful rapid pulse. This one keeps his hands in his sleeves in a warm room. 彼者身熱面赤、口渴、口瘡、脈數有力。此人於溫室之中猶袖其手。"}]},
  {t:"He passes a great deal of clear urine and yet his ankles swell. How can both be true?",z:"小便清長而踝反腫，二者何以並存？",
   o:[{a:"Yang drives qi transformation, and qi transformation is what distributes water; volume passed is not the same as water moved 陽主氣化，氣化行水；溲之量非水之得行",ok:1,n:"When two findings seem to contradict, that is usually where the mechanism is hiding. <b>Clear and copious</b> is the signature of cold — no heat to concentrate the urine — and nocturia points at the Kidney. The water in his ankles is water that qi transformation never distributed in the first place; it obeys gravity through the day and redistributes when he lies down, which is why it is worse by evening and gone by morning. 凡二證似相反者，其機每藏於其間。<b>清長</b>者寒之候：無熱以灼之。夜尿頻多，尤指於腎。其踝間所聚者，本氣化所未嘗布散之水；晝則隨地而下，臥則復散，故暮甚而朝輕。"},
      {a:"The Bladder is inflamed 膀胱有熱",ok:0,n:"Bladder damp-heat gives urgency, burning and frequency with dark scanty urine. His is clear, copious and painless. 膀胱濕熱者，尿急、尿痛、尿頻而短赤。今其溲清長而無痛。"},
      {a:"He simply drinks too much at night 但夜飲過多耳",ok:0,n:"That would not produce cold limbs, weak knees, palpitations, a pale wet tongue and a deep slow pulse. 若然，則不當見肢冷、腰膝痠軟、心悸、舌淡滑、脈沉遲。"}]},
  {t:"If this is left untreated, where does it go — and what would tell you it had gone there?",z:"此證不治，傳於何？何以知其已傳？",
   o:[{a:"水氣凌心 — water climbs and presses on the Heart: palpitations worse lying down, breathlessness that forces him to sit up, swelling rising above the ankle, a pulse that begins to pause",ok:1,n:"Knowing the destination is what makes the screening questions meaningful rather than ritual. Yang keeps failing, qi transformation keeps failing, water keeps accumulating — and it does not stay at the ankles. Re-ask at every visit: can he still lie flat? has the swelling climbed? does the pulse pause, and how often? Any of those and the answer is not a stronger prescription but a physician, promptly, alongside whatever you are doing. Tell the patient in his own words which changes to report. 知其所往，則篩查非為儀節而有其實。陽衰不已，氣化不行，水積不止，且不止於踝。逐診當再問：猶能平臥否？腫已過踝否？脈始歇止否，其數幾何？有其一者，所當為非增其方之力，乃即令就醫，而所治不廢。且當以其能記之語，明告何者當來報。"},
      {a:"It becomes yin deficiency 久則轉為陰虛",ok:0,n:"Long yang deficiency can eventually injure yin, but that is a late complication, not the near destination. 陽虛既久誠可及陰，然此遲而後至之變，非其近路。"},
      {a:"It stays where it is — ankle swelling in an old man is age 止於其處，老人踝腫，年事而已",ok:0,n:"Age explains why he is vulnerable, not what is happening. And a pattern that no longer lifts in spring, as it used to, is a pattern that is moving. 年高者言其所以易受，非言其所患。且素能隨春而解，今不解矣——其病方行。"}]}],
 teach:"Yang deficiency of the Heart and Kidney is the cold end of the water-and-fire axis, and it is worth holding beside its opposite: 心腎不交 in the insomnia chapters is the same two organs failing to communicate because the <i>water</i> is short, and that patient is hot, restless and fast-pulsed. Here the <i>fire</i> is short, and the giveaway is the tongue — pale, swollen, tooth-marked and visibly wet. Treatment warms from the root at CV4 and the Kidney points rather than from the chest where the symptom is loudest, and moxa is not merely permitted but is the main treatment. And the screening comes first: palpitations with oedema and breathlessness is the combination you never wave through.",
 teachZ:"心腎陽虛者，水火之軸之寒端，當與其反者並記：不寐諸章之心腎不交，同為二臟不交，而所虧者<b>水</b>，其人熱、煩、脈數。今所虧者<b>火</b>，而決之者在舌——淡、胖、有齒痕而滑。其治溫自下起，取關元與腎家諸穴，不取胸中證之最著處；灸非特可用，且為主治。而篩查當先於一切：心悸兼浮腫、氣促者，斷不可輕放。"}

,

{p:"暑濕困阻 Summer-Heat with Damp",tier:4,pair:"風熱犯肺",
 v:"A 34-year-old delivery rider in the third week of a hot, wet August. Heavy limbs and a head that feels wrapped in cloth; low fever that does not break with sweating; chest and epigastrium feel stuffed; thirsty but does not want to drink much; nausea, no appetite, loose sticky stool. Tongue: red with a greasy yellow coating. Pulse: soft and rapid.",
 vz:"34歲送貨騎手，八月濕熱第三週。四肢困重，頭重如裹；身熱不揚，汗出而熱不解；胸脘痞悶；口渴而不欲多飲；噁心納呆，大便溏而黏滯。舌紅苔黃膩，脈濡數。",
 q:[{t:"Sweating does not break the fever. What does that tell you?",z:"汗出而熱不解，此何謂？",
   o:[{a:"Damp is holding the heat in — sweat clears heat, but damp is sticky and stays 濕遏熱伏，汗能泄熱而濕不去",ok:1,n:"One of the most useful single observations in a summer fever. In plain heat, sweating breaks the fever. Here the damp is a sticky wrapper: the heat escapes briefly and rebuilds behind it, so the patient sweats repeatedly and stays warm. 暑月發熱，此一觀最有用。單熱者，汗出則熱退。今濕如黏裹：熱暫泄而復生於其後，故汗屢出而身仍溫。"},
      {a:"The exterior has not been released yet 表未解",ok:0,n:"An unresolved exterior comes with aversion to cold and a floating pulse, and it is days old, not weeks. 表未解者，惡寒而脈浮，其病以日計，非以旬計。"},
      {a:"The patient is yin deficient 陰虛",ok:0,n:"Yin deficiency sweats at night and stops on waking, with a peeled tongue. His coat is thick and greasy. 陰虛者盜汗，醒則止，舌剝。今其苔厚膩。"}]},
  {t:"He is thirsty but does not want to drink. Why?",z:"渴而不欲飲，何故？",
   o:[{a:"Damp is blocking the middle and holding fluid where it is not wanted 濕阻中焦，水停不化",ok:1,n:"渴不欲飲 is one of the cleanest damp markers there is. The mouth is dry because fluid is not being distributed, not because it has been boiled away — so there is no room for more. Contrast full heat, which wants cold water in quantity. 「渴不欲飲」為濕之定證。口乾者，津不布也，非為熱煎，故身無所容。實熱則大渴引冷而量多，適相反。"},
      {a:"He has drunk enough already 已飲足",ok:0,n:"Then the mouth would not be dry. The contradiction is the finding. 若然，則口不當乾。其相牴牾處，正其所診。"},
      {a:"Fluids are severely depleted 津大傷",ok:0,n:"Severe fluid depletion produces real thirst with a dry peeled tongue, not a greasy coat. 津大傷者真渴，舌乾而剝，非苔膩。"}]},
  {t:"Which direction does the treatment take?",z:"其治當從何向？",
   o:[{a:"Aromatically transform damp and clear summer-heat, and open the urine 芳香化濕、清暑，兼利小便",ok:1,n:"Damp needs an exit and heat needs cooling, and the order matters: cold bitter herbs alone are cloying and make damp worse. Aromatic herbs open the middle, bland herbs give water a road out, and only a little cooling is needed. 濕須有路，熱須得清，而其序有別：徒用苦寒則滋膩而濕愈甚。芳香開其中，淡滲利其下，而清熱少佐可也。"},
      {a:"Strongly release the exterior with sweating 峻汗解表",ok:0,n:"Sweating a damp-heat patient wastes fluids while the damp stays exactly where it was. 濕熱而峻汗者，徒傷其津而濕仍在。"},
      {a:"Warm and tonify the middle 溫補中焦",ok:0,n:"There is an excess here, not a deficiency. Tonifying feeds it. 此有餘而非不足，補之則養其邪。"}]}],
 teach:"Summer-heat 暑 rarely arrives alone in a wet climate: it comes with damp attached, and the pair produces a fever that will not break, a body that feels heavy, and a mouth that is dry without wanting water. The single most useful question is what happens after sweating. Cold bitter herbs alone make it worse — damp needs an exit, not just a cooling.",
 teachZ:"濕地之暑，鮮有獨至者，必挾濕而來。二邪並見則熱不揚、身困重、口乾而不欲飲。所最當問者，汗後何如。徒投苦寒則反甚——濕當有出路，非但清之而已。"},

{p:"涼燥犯肺 Cool-Dryness invading the Lung",tier:5,pair:"溫燥犯肺",
 v:"A 41-year-old woman in mid-October, ill four days. Dry cough with almost no phlegm; nose and throat dry; slight aversion to cold with a mild headache; no sweating; no thirst for cold drinks and no sore throat. Tongue: thin white coating, dry. Pulse: floating and tight.",
 vz:"41歲女性，十月中旬，病四日。乾咳無痰；鼻咽乾燥；微惡寒，頭微痛；無汗；不渴冷飲，咽不痛。舌苔薄白而乾，脈浮緊。",
 q:[{t:"Autumn dryness splits in two. Which half is this?",z:"秋燥有二，此屬何者？",
   o:[{a:"Cool-dryness 涼燥 — dryness with cold on the surface",ok:1,n:"Autumn runs warm at the start and cool at the end, and dryness borrows the temperature of the moment. <b>溫燥</b>, early autumn: dry cough with a sore throat, thirst for cold, fever more than chills, a thin yellow dry coat, a floating rapid pulse. <b>涼燥</b>, late autumn: the same dryness with chills more than fever, no sweating, no sore throat, a thin white dry coat, a floating tight pulse. Same pathogen, opposite thermal sign, opposite prescription. 秋初則溫，秋末則涼，而燥氣隨其時而異其性。<b>溫燥</b>者：乾咳咽痛、渴喜冷飲、熱重於寒、苔薄黃而乾、脈浮數。<b>涼燥</b>者：同一燥而寒重於熱、無汗、咽不痛、苔薄白而乾、脈浮緊。同邪而寒熱相反，其方亦反。"},
      {a:"Warm-dryness 溫燥",ok:0,n:"That patient has a sore throat, wants cold drinks, and has a yellow coat and a rapid pulse. This one has none of those. 溫燥者咽痛、喜冷飲、苔黃、脈數。本案皆無。"},
      {a:"Wind-cold with no dryness at all 單純風寒",ok:0,n:"Close, and the dry nose, dry throat and dry cough with no phlegm are what add dryness on top. Plain wind-cold gives thin clear phlegm. 近之，而鼻咽乾、乾咳無痰者，燥之所加也。單風寒者，痰清稀。"}]},
  {t:"What treats it?",z:"其治為何？",
   o:[{a:"Gently release the exterior with acrid-warm herbs and moisten the Lung 輕宣涼燥、潤肺",ok:1,n:"Both halves matter and neither is heavy. Acrid-warm to move the surface cold, moistening to answer the dryness — and gently, because a dry Lung will not take strong dispersing herbs. Xing Su San is the classical answer. 二者並行而俱宜輕。辛溫以散其表寒，潤以應其燥；而必輕者，肺既燥則不受峻散。杏蘇散，古之定方。"},
      {a:"Cold bitter herbs to drain Lung heat 苦寒清瀉肺熱",ok:0,n:"There is no heat: no sore throat, no thirst, no yellow coat, no rapid pulse. 本案無熱：咽不痛、不渴、苔不黃、脈不數。"},
      {a:"Rich yin tonics 濃厚滋陰之品",ok:0,n:"The dryness here is an external pathogen four days old, not depleted yin. Rich tonics with a pathogen still on the surface trap it inside. 此燥為外邪，病才四日，非陰虧。邪在表而投滋膩，是留邪於內。"}]},
  {t:"What in the case rules out yin deficiency?",z:"何據可排除陰虛？",
   o:[{a:"It is four days old, the coat is present and white, and there is aversion to cold with a floating pulse 病僅四日，苔薄白而有，惡寒脈浮",ok:1,n:"Three independent reasons. Yin deficiency is slow, not four days. Its tongue loses its coat rather than keeping a white one. And it does not produce aversion to cold or a floating pulse — those say a pathogen is on the surface. 三據獨立。陰虛之成以月計，非四日。其舌當苔剝，非苔薄白而在。且不當惡寒、脈浮——此二者言邪在表。"},
      {a:"She is only forty-one 年方四十一",ok:0,n:"Age does not rule out a pattern. The findings do. 年不足以排除證，證據乃可。"},
      {a:"Nothing rules it out 無據可排除",ok:0,n:"Then the two would be indistinguishable, and they are not — the timeline and the coat alone separate them. 若然，則二者不可辨；而實可辨：但憑病程與舌苔已足。"}]}],
 teach:"Autumn dryness borrows the temperature of the month. Early autumn is 溫燥 — dry with a sore throat, thirst, a yellow coat, a rapid pulse. Late autumn is 涼燥 — the same dryness with chills, no sweat, no sore throat, a white coat, a tight pulse. Both are moistened; only one is warmed. And an external dryness four days old is not the same thing as depleted Lung yin, however similar the cough sounds.",
 teachZ:"秋燥隨月而異其溫。秋初為溫燥：乾而咽痛、口渴、苔黃、脈數。秋末為涼燥：同一燥而惡寒、無汗、咽不痛、苔白、脈緊。二者俱當潤，而惟一者當溫。且外燥四日，與肺陰久虧，其咳雖似，其病不同。"},

{p:"食滯胃脘 Food Stagnation in the Stomach",tier:2,pair:"脾氣虛",
 v:"A 29-year-old man the morning after a wedding banquet. Epigastrium distended and painful, worse with pressure; belching that smells of the meal; no appetite at all and the thought of food is unpleasant; foul-smelling loose stool once, after which the distension eased slightly. Tongue: thick greasy coating. Pulse: slippery and forceful.",
 vz:"29歲男子，赴喜宴之次晨。脘腹脹痛拒按；噯氣有食臭；全無食慾，聞食則惡；瀉下一次，臭穢，瀉後脹稍減。舌苔厚膩，脈滑有力。",
 q:[{t:"He has no appetite, like a Spleen-deficient patient. What separates them?",z:"其人不欲食，似脾虛。何以別之？",
   o:[{a:"His distension refuses pressure and eases after passing stool; Spleen deficiency is better with pressure and worse when tired 拒按，瀉後減；脾虛則喜按，勞則甚",ok:1,n:"The two most useful discriminators in the whole of abdominal diagnosis. <b>Excess</b>: distension that refuses pressure, foul belching, relief after the bowels move, a thick coat, a forceful pulse. <b>Deficiency</b>: distension that welcomes a warm hand, worse when tired or after cold food, a thin coat, a weak pulse. Both patients say &#39;I have no appetite&#39;; the abdomen answers the question the words cannot. 腹診之辨，此二者最有用。<b>實</b>者：脹而拒按、噯腐、便後則減、苔厚、脈有力。<b>虛</b>者：脹而喜溫按、勞則甚、食冷則甚、苔薄、脈弱。二人同言不欲食，而其腹自能答其口所不能答者。"},
      {a:"His age 其年少",ok:0,n:"Young people get Spleen deficiency too. 少年亦有脾虛者。"},
      {a:"The banquet 因赴宴故",ok:0,n:"The history points the way, but a weak Spleen also fails after a banquet. Confirm on the abdomen and the pulse, not on the story. 其history誠有所指，然脾虛者宴後亦困。當驗之於腹與脈，不當但據其事。"}]},
  {t:"What is the treatment principle?",z:"其治法為何？",
   o:[{a:"Disperse food accumulation and harmonise the stomach 消食導滯，和胃",ok:1,n:"Bao He Wan is the classical answer, and note that it contains a small amount of Fuling and Chenpi — dispersing without abandoning the middle burner that has to do the work. 保和丸為古之定方。當察其中亦有茯苓、陳皮：消而不忘其運，中焦仍須任事。"},
      {a:"Strongly tonify the Spleen 峻補脾氣",ok:0,n:"Adding to a stomach that is already overloaded. Clear first; support afterwards, if it is still needed. 胃已壅滯而復益之。當先消而後補，且視其猶需與否。"},
      {a:"Warm the interior and dispel cold 溫裡散寒",ok:0,n:"There is no cold sign — no cold limbs, no preference for warmth, no clear copious urine. 本案無寒候：無肢冷、不喜溫、小便不清長。"}]},
  {t:"What should he be told about the next few days?",z:"數日之內，當囑其何事？",
   o:[{a:"Eat lightly and less for two or three days, and let the middle recover before feeding it 二三日內減食清淡，俟中焦復而後進",ok:1,n:"The advice is half the treatment and costs nothing. A middle burner that has just been overwhelmed does not need a tonic; it needs a short rest and simple food. Telling the patient this in plain words is more useful than any herb they will not take. 醫囑即其治之半，且不費一錢。中焦方受其困，不須進補，但須小休而食簡。以其能記之語告之，勝於一味彼所不肯服之藥。"},
      {a:"Fast completely for two days 絕食二日",ok:0,n:"Unnecessary and counterproductive, and in anyone with a medical condition it is unsafe advice. Light eating, not none. 不必如是，且反傷其正；若素有宿疾者，此囑為不安。當減食，非絕食。"},
      {a:"Eat a large tonic meal to rebuild strength 進大補之膳以復其力",ok:0,n:"The opposite of what an overloaded middle burner needs. 中焦方壅，此適反其所需。"}]}],
 teach:"Food stagnation is the commonest excess pattern nobody names, and it is worth being able to spot in one question: does the distension refuse pressure or welcome it? Refusing means excess and dispersing; welcoming means deficiency and supporting. Belching that smells of the meal, relief after the bowels move, a thick greasy coat and a forceful slippery pulse complete the picture — and the dietary advice is half the prescription.",
 teachZ:"食滯者，最常見而最少被名之實證。一問可決：其脹拒按乎？喜按乎？拒按則實，當消；喜按則虛，當補。噯腐、便後減、苔厚膩、脈滑有力，其證乃全——而醫囑之飲食，實居其治之半。"},

{p:"腎不納氣 Kidney Failing to Grasp Qi",tier:5,pair:"肺氣虛",
 v:"A 68-year-old retired stonemason with breathlessness for two years, worse this winter. The breathlessness is worse on <b>inhaling</b> — he can push air out but cannot draw it deep; worse on any exertion; weak sore low back and knees; sweating on the forehead with the effort of breathing; cold hands and feet; passes urine when he coughs hard. Tongue: pale. Pulse: deep, thin, and very weak at the chi position.",
 vz:"68歲退休石匠，氣喘二年，今冬益甚。喘以<b>吸</b>為難，呼出尚可而吸不能深；動則尤甚；腰膝痠軟；喘則額汗；手足不溫；咳甚則遺尿。舌淡，脈沉細，尺部尤弱。",
 q:[{t:"Breathlessness worse on inhaling rather than exhaling. What does that locate?",z:"喘以吸為難而非以呼為難，此定其病在何？",
   o:[{a:"The Kidney — it is the Kidney that grasps qi and draws the breath down 腎主納氣",ok:1,n:"The classical division is exact and clinically useful. <b>The Lung governs qi and respiration</b> — Lung patterns give difficulty pushing air out, a weak cough, a low voice, spontaneous sweating. <b>The Kidney grasps qi</b> 腎主納氣 — Kidney patterns give difficulty drawing air in, worse on exertion, with a weak low back, cold limbs and a deep weak chi pulse. Ask which half of the breath is hard; the answer names the organ. 其分甚確而有實用。<b>肺主氣司呼吸</b>：肺病則呼出為難，咳而無力、聲低、自汗。<b>腎主納氣</b>：腎病則吸入為難，動則益甚，兼腰膝痠軟、肢冷、尺脈沉弱。但問呼吸孰難，而臟自見。"},
      {a:"The Lung alone 但在肺",ok:0,n:"The Lung is involved in any chronic breathlessness, but it does not explain a weak back, cold limbs, incontinence on coughing, or a chi pulse you cannot find. 久喘未有不涉肺者，然肺不能解腰膝、肢冷、咳而遺尿、尺脈難尋。"},
      {a:"The Heart 在心",ok:0,n:"Heart patterns bring palpitations, and often oedema and a pulse that pauses. He has neither. 心病者兼心悸，多見浮腫、脈歇止。本案皆無。"}]},
  {t:"He passes urine when he coughs. How does that fit?",z:"咳則遺尿，於證何合？",
   o:[{a:"The Kidney governs the two lower orifices and holds them closed; when Kidney qi is weak, the holding fails 腎司二陰，腎氣虛則失其固攝",ok:1,n:"Not an embarrassing aside — a confirming sign. The same weakness that cannot draw the breath down cannot hold the lower gate. Ask about it gently and directly; patients almost never volunteer it, and it is one of the clearest Kidney-qi markers there is. 此非可略之瑣事，乃佐證也。不能納氣者，即不能固下竅，其虛一也。當溫言而直問之：病人幾不自言，而腎氣不固之候，未有明於此者。"},
      {a:"It is unrelated and just age 與病無涉，年老而已",ok:0,n:"Age explains susceptibility, not mechanism — and dismissing it loses a finding that ties the case together. 年高者言其所以易受，非言其機。棄之，則失一貫串全案之據。"},
      {a:"Damp-heat in the bladder 膀胱濕熱",ok:0,n:"That brings urgency, burning and dark urine. This is leaking under pressure, not urgency. 彼者尿急、尿痛、溲赤。此為壓力之下失禁，非急也。"}]},
  {t:"Which point pair goes to the root here?",z:"取何穴以治其本？",
   o:[{a:"Shenshu BL23 and Guanyuan CV4, warmed 腎俞配關元，並灸",ok:1,n:"Back-Shu with Front-Mu, warming the Kidney from behind and in front at once. Add Feishu BL13 and Taiyuan LU9 for the Lung end of the breath, and Zusanli ST36 to build the supply. Warm, gentle, and repeated — this is a pattern treated over months. 俞募相配，前後夾溫其腎。兼取肺俞、太淵以理其上，足三里以資其源。宜溫、宜輕、宜屢——此證以月計。"},
      {a:"Chize LU5 and Fenglong ST40, reduced 尺澤配豐隆，用瀉",ok:0,n:"Those clear Lung heat and transform phlegm — a full pattern. This one is empty from the root. 此清肺熱、化痰之法，所主為實。本案本虛。"},
      {a:"Hegu LI4 and Taichong LR3 開四關",ok:0,n:"The Four Gates move qi through the whole body. There is not enough qi here to move. 四關行一身之氣。本案氣本不足，無可行者。"}]}],
 teach:"Two organs govern the breath and they divide it cleanly: the Lung pushes air out, the Kidney draws it in. Chronic breathlessness that is worse on inhaling, worse on exertion, and comes with a weak low back, cold limbs and a deep weak chi pulse is the Kidney failing to grasp qi — and the leaking bladder on a hard cough is the same failure of holding, seen at the other end. Treated by warming and supplementing the root over months, not by clearing the chest.",
 teachZ:"司呼吸者二臟，其分甚明：肺主呼，腎主納。久喘而吸為難、動則甚，兼腰膝痠軟、肢冷、尺脈沉弱者，腎不納氣也；咳甚遺尿，即同一不固而見於下竅。其治在溫補其本，以月計，而不在清其胸。"}

,

{p:"中風先兆 Warning Signs of Wind-Stroke 肝陽化風",tier:5,pair:"肝陽上亢",
 v:"A 63-year-old man brought in by his daughter twenty minutes ago. While eating breakfast his right hand went weak and dropped the bowl; the right side of his mouth is drooping; his speech is slurred and he is searching for words. He is awake and knows where he is. He has a long history of headaches, dizziness and a wiry pulse. Tongue: red. Pulse: wiry and forceful.",
 vz:"63歲男子，其女送來，發病二十分鐘。早餐時右手忽然無力，碗落於地；右側口角歪斜；言語不清，覓字困難。神清，知其所在。素有頭痛、眩暈，脈弦。舌紅，脈弦有力。",
 q:[{t:"What do you do first?",z:"首當何為？",
   o:[{a:"Call emergency services now — sudden one-sided weakness, facial droop and slurred speech is a medical emergency and every minute counts 立即呼叫急救。突發偏側無力、口角歪斜、言語不清，屬急症，分秒必爭",ok:1,n:"<b>This is the only correct answer and it is not a pattern question.</b> Sudden weakness on one side, a drooping face, slurred or lost speech, sudden severe headache, sudden loss of vision, sudden loss of balance — any one of these, call emergency services immediately. The treatments that help most are time-limited and measured in minutes. Note the time symptoms began and tell the responders; that single number changes what can be offered. Do not needle first, do not give herbs first, do not wait to see whether it passes.<br><b>此為惟一之答，且非辨證之問。</b>突發偏側無力、口角歪斜、言語不清或失語、劇烈頭痛、驟然失明、驟然失衡——見其一者，即刻呼叫急救。所能救者，其法有時限，以分計。當記其發病之時刻而告救者：此一數，能改所能施之治。勿先針、勿先藥、勿俟其自解。"},
      {a:"Take a full pulse and tongue reading, then decide 詳診脈舌而後定",ok:0,n:"The pattern can be named on the way to hospital or afterwards. It cannot be named instead. Time spent examining is time taken from a treatment window that closes. 其證可於送醫途中或事後而名之，不可以名證代送醫。診察所費之時，即奪其可治之窗。"},
      {a:"Needle Baihui and Taichong to subdue the yang 針百會、太衝以潛其陽",ok:0,n:"Acupuncture has a genuine and well-studied place in stroke <i>rehabilitation</i>. It is not the first response to an acute event, and reaching for it first delays the thing that actually helps. 針灸於中風<b>康復</b>之期，其用有據。然非急性發作之首務；先取此者，適延其所真賴。"}]},
  {t:"What is the pattern called, and why is that still worth knowing?",z:"其證何名？既已送醫，何以猶當知之？",
   o:[{a:"Liver yang transforming into wind 肝陽化風 — and it matters for the months of recovery afterwards",ok:1,n:"Long-standing Liver yang rising — headaches, dizziness, a wiry forceful pulse, a red tongue — can tip into internal wind, which moves suddenly and strikes one side. Naming it does nothing in the first hour. It shapes everything afterwards: the rehabilitation, the pattern to treat between sessions, and the years of prevention in someone who has been told twice already that their pulse is wiry. 素有肝陽上亢——頭痛、眩暈、脈弦有力、舌紅——久則化風，風性善行而數變，故猝然偏中。名之於首一時辰無所用，而於其後則盡有所用：康復之法、平日所當治之證，及其人素被告以脈弦者，數年之防。"},
      {a:"Wind-cold invading the channels 風寒襲絡",ok:0,n:"External wind gives aversion to cold, a floating pulse and a new illness of days. This is internal wind on a two-decade background. 外風者惡寒、脈浮，其病以日計。此為內風，其本二十年。"},
      {a:"Phlegm-damp obstructing 痰濕阻滯",ok:0,n:"Phlegm is often part of a stroke picture and may well be here, but the sudden one-sided onset in a man with years of wiry pulse and headache is wind. 中風之候誠多兼痰，本案或亦有之；然猝發偏中，而其人素脈弦頭痛者，風也。"}]},
  {t:"His daughter asks what she should watch for in future. What is the most useful thing to tell her?",z:"其女問日後當察何事。最有用之言為何？",
   o:[{a:"The specific sudden signs, in plain words, and to call immediately rather than wait 以淺白之語告其急症之徵，並囑即刻呼救而勿觀望",ok:1,n:"Say them so she can repeat them: face drooping on one side, one arm weak, speech slurred — call now, note the time. Add that brief episodes that resolve within minutes still need urgent assessment, because they warn of what is coming. This is the single most valuable sentence in the whole consultation, and it costs nothing to say. 當言其可複述者：一側面歪、一臂無力、言語不清——即刻呼救，並記其時。且告之：症狀雖數分鐘而自解，仍須即刻就醫，蓋其為將來之兆。此診中最有價值之一語，而言之不費一錢。"},
      {a:"A list of foods to avoid 列所忌之食",ok:0,n:"Diet belongs in the long conversation. It is not what she needs to hear in the next ten seconds. 飲食之宜忌，屬日後之長談。非其十秒之內所當聞者。"},
      {a:"To bring him for acupuncture twice a week 囑其每週兩診針灸",ok:0,n:"Reasonable for rehabilitation, and it will be discussed — after she knows what to do if it happens again. 康復之期，此議可行——然當俟其先知再發之際何為。"}]}],
 teach:"Some presentations are not pattern-differentiation problems. Sudden one-sided weakness, facial droop, slurred speech, sudden severe headache, sudden vision loss or sudden loss of balance means emergency services, immediately, and note the time symptoms began. The TCM reading — Liver yang transforming into internal wind on a long background of rising yang — is real and shapes months of rehabilitation and years of prevention. It does not shape the first hour. Knowing which questions are not yours to answer alone is part of the training.",
 teachZ:"有些病證，非辨證之問。突發偏側無力、口角歪斜、言語不清、劇烈頭痛、驟然失明或失衡者，即刻呼叫急救，並記其發病時刻。中醫之讀——素體肝陽上亢，久而化風——其說不謬，且於數月之康復、數年之預防皆有所主；惟於首一時辰無所主。知何問不可獨決，亦醫者之學也。"},

{p:"心膽氣虛 Heart and Gallbladder Qi Deficiency",tier:5,pair:"痰火擾心",
 v:"A 26-year-old woman, six months after a road accident she was not injured in. Sleeps poorly and wakes at any sound; startles violently at nothing; timid about decisions she used to make easily; palpitations when startled that settle slowly; sighing; dreams a great deal. No bitter taste, no thirst, no phlegm. Tongue: pale with a thin white coating. Pulse: thin and slightly wiry, without force.",
 vz:"26歲女性，半年前遇車禍而身未受傷。寐淺，聞聲即醒；無故易驚；素能決之事，今則怯而不決；驚則心悸，久乃平；時太息；多夢。無口苦、無渴、無痰。舌淡苔薄白，脈細略弦而無力。",
 q:[{t:"She startles easily, like the phlegm-fire patient. What separates them?",z:"其人易驚，似痰火擾心。何以別之？",
   o:[{a:"Everything about her is empty — pale tongue, thin coat, forceless pulse, no bitter mouth, no phlegm 通身皆虛：舌淡、苔薄、脈無力，無口苦、無痰",ok:1,n:"Same headline symptom, opposite mechanism. <b>痰火擾心</b>: the spirit is being <i>harassed</i> — agitation, thick greasy yellow coat, bitter mouth, thick phlegm, a forceful slippery rapid pulse; treated by clearing and draining. <b>心膽氣虛</b>: the spirit is <i>unanchored</i> — timidity, indecision, a pale tongue, a thin forceless pulse, nothing thick anywhere; treated by supplementing and settling. Look at the coat and feel for force; those two settle it. 同一主證而其機相反。<b>痰火擾心</b>者，神受<b>擾</b>：躁、苔黃厚膩、口苦、痰稠、脈滑數有力，治以清瀉。<b>心膽氣虛</b>者，神失<b>守</b>：怯、不決、舌淡、脈細無力，通身無厚膩之物，治以補而安之。察其苔、按其力，二者即判。"},
      {a:"Her age 其年少",ok:0,n:"Both patterns occur at any age. 二證於老少皆有。"},
      {a:"The accident 因車禍故",ok:0,n:"The history explains the trigger, not the pattern. Shock can produce either picture depending on the constitution it lands in. 其事言其因，不言其證。驚恐所致，隨其稟賦而見二證之一。"}]},
  {t:"Why the Gallbladder, alongside the Heart?",z:"何以心而兼膽？",
   o:[{a:"The Gallbladder governs decision-making 膽主決斷 — timidity and indecision are its own signs",ok:1,n:"One of the more literal correspondences in the whole system and it holds up in clinic: 膽主決斷, the Gallbladder governs judgement and decisiveness, and its deficiency shows as being easily frightened and unable to decide — 膽怯. Paired with the Heart, which houses the spirit, you get exactly this patient: startled easily, sleeps badly, and no longer trusts her own choices. 五臟諸應之中，此最為直白，而臨證可據：膽主決斷，其虛則善驚而不能決，所謂膽怯。心藏神而與之相配，則正得此人：易驚、寐差，而不復自信其所擇。"},
      {a:"Because she has a bitter taste 以其口苦故",ok:0,n:"She does not — that was asked and it is absent, which is part of what rules out the phlegm-fire reading. 本案無口苦，已問而無之；此正所以排除痰火之據。"},
      {a:"Because the Gallbladder stores bile 以膽藏膽汁故",ok:0,n:"True and not the reason here. The functional correspondence, not the anatomy, is what this pattern rests on. 語雖不誤，而非此證所繫。所繫者在其所主之用，不在其形。"}]},
  {t:"What is the treatment principle?",z:"其治法為何？",
   o:[{a:"Supplement qi and settle the spirit — An Shen Ding Zhi Wan is the classical answer 益氣鎮驚安神，方如安神定志丸",ok:1,n:"Supplement, do not clear. Needle with reinforcing method, keep the room quiet, and say what you are about to do before you do it — handling matters more than usual with a patient who startles. And take the trigger seriously: six months of this after a frightening event deserves being asked, gently, how she is doing more broadly. 當補不當清。行針用補法，室宜靜，未刺先告——易驚之人，其手法之輕重，尤重於他證。且當視其所由：驚後半年而猶如此者，宜溫言而問其近況之全。"},
      {a:"Clear phlegm-fire and settle the spirit 清痰火而安神",ok:0,n:"There is no phlegm and no fire. Draining an empty patient takes away what little she has. 本案無痰無火。虛而瀉之，是奪其僅存。"},
      {a:"Course the Liver and move qi vigorously 峻疏肝行氣",ok:0,n:"The sighing is real, but vigorous moving in a qi-deficient patient spends what is already short. Support first; move gently if at all. 太息誠有之，然氣本不足而峻行之，是耗其所少。當先補，行則宜輕。"}]}],
 teach:"Two patterns share the headline symptom of being easily startled and they are opposites. Phlegm-fire harasses a spirit that has too much around it: agitation, a thick greasy yellow coat, a bitter mouth, a forceful slippery pulse — clear it. Heart and Gallbladder qi deficiency leaves a spirit with too little holding it: timidity, indecision, a pale tongue, a thin forceless pulse — supplement it. The tongue coat and the force of the pulse settle it in two seconds. And 膽主決斷 is not decoration; a patient who has stopped trusting her own decisions is telling you which organ to name.",
 teachZ:"二證同以易驚為其主訴，而適相反。痰火者，神為有餘之物所<b>擾</b>：躁、苔黃厚膩、口苦、脈滑有力，當清之。心膽氣虛者，神失所<b>守</b>：怯、不決、舌淡、脈細無力，當補之。察苔與脈力，二秒可判。且「膽主決斷」非虛設之語：其人不復自信其所擇，即已告你當名何臟。"},

{p:"寒凝血瘀 · 痛經 Cold Congealing with Blood Stasis",tier:5,pair:"氣滯血瘀",
 v:"A 24-year-old woman with painful periods since her teens, worse in the past two winters. Pain begins a day before the flow and is cold and cramping, low in the abdomen, <b>much better with a hot water bottle</b> and worse if she sits on cold ground. Flow is scanty at first, dark with small clots, and the pain eases once the clots pass. Cold hands and feet. Tongue: dark purple with a white coating. Pulse: deep and tight.",
 vz:"24歲女性，自少女時痛經，近二冬益甚。經前一日始痛，冷痛拘急，在小腹，<b>得熱則大減</b>，坐冷地則甚。經初量少，色暗有小血塊，塊下則痛減。手足不溫。舌紫暗，苔白，脈沉緊。",
 q:[{t:"What single question separates this from qi-stagnation stasis?",z:"一問可別此於氣滯血瘀者，何問？",
   o:[{a:"Does warmth help? — cold stasis is dramatically better with heat 得熱則減否？寒凝者得熱而大減",ok:1,n:"The most useful question in period pain, and the answer is usually unmistakable. <b>寒凝血瘀</b>: cold cramping pain, much better with heat, worse with cold, dark flow with clots, cold limbs, a white coat, a deep tight pulse — warm the channels and dispel cold. <b>氣滯血瘀</b>: distending pain that moves and comes with breast tenderness and irritability before the period, better after a sigh or a good cry, a wiry pulse — course the Liver and move qi. Both have clots. Only one wants a hot water bottle. 痛經諸問，此最有用，而其答多不待疑。<b>寒凝血瘀</b>：冷痛拘急、得熱大減、遇寒則甚、經色暗有塊、肢冷、苔白、脈沉緊——當溫經散寒。<b>氣滯血瘀</b>：脹痛而走竄，經前乳脹、煩躁，太息或一哭則舒，脈弦——當疏肝行氣。二者俱有血塊，而惟一者求湯婆子。"},
      {a:"Is the pain before or after the flow? 痛在經前抑經後？",ok:0,n:"Useful — before the flow generally means excess, after generally means deficiency — but it does not separate these two, since both are excess and both hurt before. 此問誠有用：經前多實，經後多虛。然不能別此二者，蓋二者俱實而俱痛於經前。"},
      {a:"How heavy is the flow? 經量多少？",ok:0,n:"Also useful and also shared: both patterns tend to a scanty, dark, clotted start. 此問亦有用，而二證亦同：俱初量少、色暗、有塊。"}]},
  {t:"The pain eases once the clots pass. What does that confirm?",z:"塊下則痛減，此證何事？",
   o:[{a:"Stasis — the obstruction is physical, so removing it relieves the pain 瘀也。其阻為有形，故去之則痛減",ok:1,n:"A small, precise observation. Pain that improves the moment a clot passes is telling you the pain was the obstruction. Compare qi-stagnation pain, which moves and changes with mood, and deficiency pain, which is dull, worse when tired, and welcomes pressure. 一小而確之候。塊下而痛即減者，是言其痛即在其阻。氣滯之痛則走竄而隨情志變；虛痛則綿綿、勞則甚而喜按。"},
      {a:"Deficiency 虛",ok:0,n:"Deficient period pain is dull, comes after the flow, is better with pressure and warmth, and does not clot. 虛者痛綿綿，多在經後，喜按喜溫而無血塊。"},
      {a:"Damp-heat 濕熱",ok:0,n:"That brings burning, yellow discharge, a greasy yellow coat and a slippery rapid pulse. Nothing here is hot. 彼者灼熱、帶下色黃、苔黃膩、脈滑數。本案無一熱候。"}]},
  {t:"What is the treatment, and what is worth saying out loud?",z:"其治為何？又有何言當明告之？",
   o:[{a:"Warm the channels, dispel cold and move blood — and say plainly that severe or worsening period pain deserves a medical assessment too 溫經散寒、活血止痛；並明告：痛經劇烈或漸重者，亦當就醫查之",ok:1,n:"Wen Jing Tang or Shao Fu Zhu Yu Tang classically, moxa on the lower abdomen and the low back, and warmth as daily practice rather than only during the period. And the sentence that must be said: period pain that is severe, getting worse year on year, or new in someone who did not have it deserves a gynaecological assessment. Treating a pattern well and referring appropriately are not in competition. 古方如溫經湯、少腹逐瘀湯，小腹與腰俞加灸，而溫養宜為日常，不獨於經期。而必當明言者：痛經劇烈、逐年加重，或素無而今始有者，宜就婦科查之。善治其證與適時轉介，二者不相妨。"},
      {a:"Cool the blood and clear heat 涼血清熱",ok:0,n:"The opposite direction. Cooling a cold-congealed abdomen makes the pain worse. 其向適反。寒凝之腹而復涼之，其痛益甚。"},
      {a:"Tell her it is normal and will pass with age 告以此為常，年長自愈",ok:0,n:"Dismissing pain is not treatment, and it is how a treatable condition goes unassessed for a decade. 輕其痛者非治也；可治之病，其所以十年不得診者，多由於此。"}]}],
 teach:"Period pain divides first on one question: does warmth help? Cold congealing with stasis is cold, cramping, dramatically better with heat, worse with cold, with dark clotted flow and a deep tight pulse — warmed and moved. Qi stagnation with stasis is distending, movable, worse with frustration, with breast tenderness and a wiry pulse — coursed and moved. Both clot; only one wants heat. And whatever the pattern, severe, worsening or newly-arrived period pain deserves a medical assessment alongside.",
 teachZ:"痛經之辨，首在一問：得熱則減否？寒凝血瘀者，冷痛拘急、得熱大減、遇寒則甚，經色暗有塊，脈沉緊，當溫而行之。氣滯血瘀者，脹痛走竄、鬱怒則甚，兼乳脹，脈弦，當疏而行之。二者俱有塊，而惟一者求熱。且不論何證：痛經劇烈、漸重，或素無而新起者，皆當並就醫查之。"}


];
